// アクセシビリティ修正用のコンポーネントとユーティリティ
// WCAG 2.1 AA準拠のためのヘルパー関数とコンポーネント

import React from 'react'

/**
 * アクセシブルなフォーム入力コンポーネント
 * WCAG 1.3.1 - フォーム要素の適切なラベル付けを保証
 */
export const AccessibleInput = ({
  id,
  label,
  type = 'text',
  value,
  onChange,
  placeholder,
  className,
  darkMode = false,
  required = false,
  ariaDescribedBy,
  ...props
}) => {
  const inputId = id || `input-${Math.random().toString(36).substr(2, 9)}`

  return (
    <div className='form-group'>
      <label
        htmlFor={inputId}
        className={`mb-2 block text-sm font-medium ${darkMode ? 'text-gray-200' : 'text-gray-700'}`}
      >
        {label}
        {required && (
          <span className='ml-1 text-red-500' aria-label='必須'>
            *
          </span>
        )}
      </label>
      <input
        id={inputId}
        type={type}
        value={value}
        onChange={onChange}
        placeholder={placeholder}
        className={className}
        required={required}
        aria-required={required}
        aria-describedby={ariaDescribedBy}
        {...props}
      />
    </div>
  )
}

