/**
 * フォーカストラップフック
 */
export const useFocusTrap = (ref) => {
  React.useEffect(() => {
    if (!ref.current) {
      return
    }

    const focusableElements = ref.current.querySelectorAll(
      'a[href], button, textarea, input[type="text"], input[type="radio"], input[type="checkbox"], select'
    )

    const firstFocusable = focusableElements[0]
    const lastFocusable = focusableElements[focusableElements.length - 1]

    const handleTabKey = (e) => {
      if (e.key !== 'Tab') {
        return
      }

      if (e.shiftKey) {
        if (document.activeElement === firstFocusable) {
          lastFocusable.focus()
          e.preventDefault()
        }
      } else {
        if (document.activeElement === lastFocusable) {
          firstFocusable.focus()
          e.preventDefault()
        }
      }
    }

    ref.current.addEventListener('keydown', handleTabKey)

    return () => {
      if (ref.current) {
        ref.current.removeEventListener('keydown', handleTabKey)
      }
    }
  }, [ref])
}

/**
 * キーボードナビゲーションフック
 */
export const useKeyboardNavigation = (items, onSelect) => {
  const [focusedIndex, setFocusedIndex] = React.useState(-1)

  React.useEffect(() => {
    const handleKeyDown = (e) => {
      switch (e.key) {
        case 'ArrowUp':
          e.preventDefault()
          setFocusedIndex((prev) => (prev <= 0 ? items.length - 1 : prev - 1))
          break
        case 'ArrowDown':
          e.preventDefault()
          setFocusedIndex((prev) => (prev >= items.length - 1 ? 0 : prev + 1))
          break
        case 'Enter':
        case ' ':
          e.preventDefault()
          if (focusedIndex >= 0 && focusedIndex < items.length) {
            onSelect(items[focusedIndex])
          }
          break
        case 'Escape':
          setFocusedIndex(-1)
          break
        default:
          break
      }
    }

    window.addEventListener('keydown', handleKeyDown)
    return () => window.removeEventListener('keydown', handleKeyDown)
  }, [focusedIndex, items, onSelect])

  return { focusedIndex, setFocusedIndex }
}

/**
 * アナウンスメントフック
 */
export const useAnnounce = () => {
  const [announcement, setAnnouncement] = React.useState('')

  const announce = React.useCallback((message) => {
    setAnnouncement('')
    setTimeout(() => setAnnouncement(message), 100)
  }, [])

  return { announcement, announce }
}

export default {
  AccessibleInput,
  AccessibleTextarea,
  AccessibleSelect,
  ScreenReaderOnly,
  SkipLink,
  AriaLiveRegion,
  FormError,
  AccessibleLoading,
  useFocusTrap,
  useKeyboardNavigation,
  useAnnounce,
}

