        </div>

        {/* Active Coaching Session */}
        {activeCoaching && (
          <div className='rounded-lg bg-gradient-to-r from-purple-50 to-blue-50 p-6 shadow-lg dark:from-purple-900/20 dark:to-blue-900/20'>
