import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '../ui/dialog'
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
  DropdownMenuSeparator,
} from '../ui/dropdown-menu'
import { Switch } from '../ui/switch'
// import { Separator } from '../ui/separator' // TODO: Will be used in future UI updates
import { ScrollArea } from '../ui/scroll-area'
import { formatDistanceToNow } from 'date-fns' // format will be used in future UI updates

interface StudyGroup {
  id: string
  name: string
  description: string
  avatar?: string
  isPrivate: boolean
  memberCount: number
  maxMembers: number
  createdBy: string
  createdAt: Date
  lastActivity: Date
  tags: string[]
  studySchedule?: {
    timezone: string
    sessions: Array<{
      dayOfWeek: number
      startTime: string
      duration: number
      topic?: string
    }>
  }
  settings: {
    allowInvites: boolean
    requireApproval: boolean
    allowFileSharing: boolean
    allowVoiceChat: boolean
  }
}

interface GroupMember {
  userId: string
  username: string
  displayName: string
  avatar?: string
  role: 'owner' | 'moderator' | 'member'
  joinedAt: Date
  lastActive: Date
  studyStreak: number
  contributionScore: number
}

interface DiscussionThread {
  id: string
  groupId: string
  title: string
  content: string
  authorId: string
  authorName: string
  authorAvatar?: string
  createdAt: Date
  updatedAt: Date
  isPinned: boolean
  isLocked: boolean
  tags: string[]
  category: 'general' | 'study' | 'exam' | 'help' | 'resource'
  replyCount: number
  likeCount: number
  viewCount: number
  lastReplyAt?: Date
  lastReplyBy?: string
  attachments: Array<{
    id: string
    name: string
    url: string
    type: string
    size: number
  }>
}

interface DiscussionReply {
  id: string
  threadId: string
  content: string
  authorId: string
  authorName: string
  authorAvatar?: string
  createdAt: Date
  updatedAt?: Date
  parentReplyId?: string
  likeCount: number
  isEdited: boolean
  attachments: Array<{
    id: string
    name: string
    url: string
    type: string
    size: number
  }>
}

interface SharedNote {
  id: string
  groupId: string
  title: string
  content: string
  authorId: string
  authorName: string
  createdAt: Date
  updatedAt: Date
  isPublic: boolean
  collaborators: string[]
  tags: string[]
  category: string
  version: number
  changeHistory: Array<{
    id: string
    authorId: string
    authorName: string
    timestamp: Date
    changes: string
  }>
}

interface Notification {
  id: string
  type:
    | 'group_invite'
    | 'thread_reply'
    | 'mention'
    | 'note_share'
    | 'group_activity'
    | 'study_reminder'
  title: string
  message: string
  data: Record<string, unknown>
  isRead: boolean
  createdAt: Date
  expiresAt?: Date
}

const EnhancedCollaborationHub: React.FC = () => {
  const { toast } = useToast()

  // Core state
  const [studyGroups, setStudyGroups] = useState<StudyGroup[]>([])
  const [activeGroup, setActiveGroup] = useState<StudyGroup | null>(null)
  const [, setGroupMembers] = useState<GroupMember[]>([])
  const [discussions, setDiscussions] = useState<DiscussionThread[]>([])
  const [activeThread, setActiveThread] = useState<DiscussionThread | null>(null)
  const [replies, setReplies] = useState<DiscussionReply[]>([])
  const [sharedNotes, setSharedNotes] = useState<SharedNote[]>([])
  const [notifications, setNotifications] = useState<Notification[]>([])
  const [isLoading, setIsLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)

  // UI state
  const [activeView, setActiveView] = useState<
    'groups' | 'discussions' | 'notes' | 'notifications'
  >('groups')
  const [showCreateGroupDialog, setShowCreateGroupDialog] = useState(false)
  const [showCreateThreadDialog, setShowCreateThreadDialog] = useState(false)
  const [showCreateNoteDialog, setShowCreateNoteDialog] = useState(false)
  const [,] = useState(false)
  const [searchQuery, setSearchQuery] = useState('')
  const [selectedCategory, setSelectedCategory] = useState<string>('all')
  const [sortBy, setSortBy] = useState<'recent' | 'popular' | 'alphabetical'>('recent')

  // Real-time state
  const [isOnline] = useState(true)
  const [onlineMembers] = useState<Set<string>>(new Set())
  const [,] = useState<Set<string>>(new Set())

  // Form state
  const [newGroup, setNewGroup] = useState({
    name: '',
    description: '',
    isPrivate: false,
    maxMembers: 50,
    tags: '',
  })

  const [newThread, setNewThread] = useState({
    title: '',
    content: '',
    category: 'general' as const,
    tags: '',
  })

  const [newNote, setNewNote] = useState({
    title: '',
    content: '',
    category: '',
    tags: '',
    isPublic: false,
  })

  const [replyContent, setReplyContent] = useState('')

  // Load data
  useEffect(() => {
    loadInitialData()

    // Set up real-time connection
    // This would normally connect to WebSocket or Server-Sent Events
    // setupRealtimeConnection();

    return () => {
      // Cleanup real-time connection
      // cleanupRealtimeConnection();
    }
  }, [])

  const loadInitialData = async () => {
    setIsLoading(true)
    setError(null)

    try {
      const [groupsData, notificationsData] = await Promise.all([
        api.collaboration.getStudyGroups.query(),
        api.collaboration.getNotifications.query({ limit: 50 }),
      ])

      setStudyGroups(groupsData)
      setNotifications(notificationsData)
    } catch (error) {
      const message = error instanceof Error ? error.message : 'Failed to load collaboration data'
      setError(message)
      toast({
        title: 'Failed to Load Data',
        description: message,
        variant: 'destructive',
      })
    } finally {
      setIsLoading(false)
    }
  }

  const loadGroupData = async (groupId: string) => {
    try {
      const [membersData, discussionsData, notesData] = await Promise.all([
        api.collaboration.getGroupMembers.query({ groupId }),
        api.collaboration.getDiscussions.query({ groupId }),
        api.collaboration.getSharedNotes.query({ groupId }),
      ])

      setGroupMembers(membersData)
      setDiscussions(discussionsData)
      setSharedNotes(notesData)
    } catch (error) {
      toast({
        title: 'Failed to Load Group Data',
        description: error instanceof Error ? error.message : 'An error occurred',
        variant: 'destructive',
      })
    }
  }

  const handleCreateGroup = async () => {
    try {
      const group = await api.collaboration.createStudyGroup.mutate({
        name: newGroup.name,
        description: newGroup.description,
        isPrivate: newGroup.isPrivate,
        maxMembers: newGroup.maxMembers,
        tags: newGroup.tags
          .split(',')
          .map((t) => t.trim())
          .filter(Boolean),
        settings: {
          allowInvites: true,
          requireApproval: newGroup.isPrivate,
          allowFileSharing: true,
          allowVoiceChat: true,
        },
      })

      setStudyGroups((prev) => [group, ...prev])
      setNewGroup({ name: '', description: '', isPrivate: false, maxMembers: 50, tags: '' })
      setShowCreateGroupDialog(false)

      toast({
        title: 'Study Group Created',
        description: `${group.name} has been created successfully.`,
      })
    } catch (error) {
      toast({
        title: 'Failed to Create Group',
        description: error instanceof Error ? error.message : 'An error occurred',
        variant: 'destructive',
      })
    }
  }

  const handleJoinGroup = async (groupId: string) => {
    try {
      await api.collaboration.joinStudyGroup.mutate({ groupId })

      // Update group member count
      setStudyGroups((prev) =>
        prev.map((group) =>
          group.id === groupId ? { ...group, memberCount: group.memberCount + 1 } : group
        )
      )

      toast({
        title: 'Joined Study Group',
        description: 'You have successfully joined the study group.',
      })
    } catch (error) {
      toast({
        title: 'Failed to Join Group',
        description: error instanceof Error ? error.message : 'An error occurred',
        variant: 'destructive',
      })
    }
  }

  const handleLeaveGroup = async (groupId: string) => {
    try {
      await api.collaboration.leaveStudyGroup.mutate({ groupId })

      setStudyGroups((prev) =>
        prev.map((group) =>
          group.id === groupId ? { ...group, memberCount: group.memberCount - 1 } : group
        )
      )

      if (activeGroup?.id === groupId) {
        setActiveGroup(null)
      }

      toast({
        title: 'Left Study Group',
        description: 'You have left the study group.',
      })
    } catch (error) {
      toast({
        title: 'Failed to Leave Group',
        description: error instanceof Error ? error.message : 'An error occurred',
        variant: 'destructive',
      })
    }
  }

  const handleCreateThread = async () => {
    if (!activeGroup) {
      return
    }

    try {
      const thread = await api.collaboration.createDiscussion.mutate({
        groupId: activeGroup.id,
        title: newThread.title,
        content: newThread.content,
        category: newThread.category,
        tags: newThread.tags
          .split(',')
          .map((t) => t.trim())
          .filter(Boolean),
      })

      setDiscussions((prev) => [thread, ...prev])
      setNewThread({ title: '', content: '', category: 'general', tags: '' })
      setShowCreateThreadDialog(false)

      toast({
        title: 'Discussion Created',
        description: 'Your discussion thread has been created.',
      })
    } catch (error) {
      toast({
        title: 'Failed to Create Discussion',
        description: error instanceof Error ? error.message : 'An error occurred',
        variant: 'destructive',
      })
    }
  }

  const handleCreateNote = async () => {
    if (!activeGroup) {
      return
    }

    try {
      const note = await api.collaboration.createSharedNote.mutate({
        groupId: activeGroup.id,
        title: newNote.title,
        content: newNote.content,
        category: newNote.category,
        tags: newNote.tags
          .split(',')
          .map((t) => t.trim())
          .filter(Boolean),
        isPublic: newNote.isPublic,
      })

      setSharedNotes((prev) => [note, ...prev])
      setNewNote({ title: '', content: '', category: '', tags: '', isPublic: false })
      setShowCreateNoteDialog(false)

      toast({
        title: 'Note Created',
        description: 'Your shared note has been created.',
      })
    } catch (error) {
      toast({
        title: 'Failed to Create Note',
        description: error instanceof Error ? error.message : 'An error occurred',
        variant: 'destructive',
      })
    }
  }

  const handleReplyToThread = async () => {
    if (!activeThread || !replyContent.trim()) {
      return
    }

    try {
      const reply = await api.collaboration.replyToDiscussion.mutate({
        threadId: activeThread.id,
        content: replyContent.trim(),
      })

      setReplies((prev) => [...prev, reply])
      setReplyContent('')

      // Update thread reply count
      setDiscussions((prev) =>
        prev.map((thread) =>
          thread.id === activeThread.id
            ? {
                ...thread,
                replyCount: thread.replyCount + 1,
                lastReplyAt: new Date(),
                lastReplyBy: 'You',
              }
            : thread
        )
      )

      toast({
        title: 'Reply Posted',
        description: 'Your reply has been posted.',
      })
    } catch (error) {
      toast({
        title: 'Failed to Post Reply',
        description: error instanceof Error ? error.message : 'An error occurred',
        variant: 'destructive',
      })
    }
  }

  const handleSelectGroup = async (group: StudyGroup) => {
    setActiveGroup(group)
    setActiveView('discussions')
    await loadGroupData(group.id)
  }

  const handleOpenThread = async (thread: DiscussionThread) => {
    setActiveThread(thread)

    try {
      const repliesData = await api.collaboration.getDiscussionReplies.query({
        threadId: thread.id,
      })
      setReplies(repliesData)

      // Mark as viewed
      await api.collaboration.markDiscussionAsViewed.mutate({
        threadId: thread.id,
      })
    } catch (error) {
      toast({
        title: 'Failed to Load Discussion',
        description: error instanceof Error ? error.message : 'An error occurred',
        variant: 'destructive',
      })
    }
  }

  const filteredGroups = studyGroups.filter((group) => {
    const matchesSearch =
      !searchQuery ||
      group.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
      group.description.toLowerCase().includes(searchQuery.toLowerCase()) ||
      group.tags.some((tag) => tag.toLowerCase().includes(searchQuery.toLowerCase()))

    return matchesSearch
  })

  const filteredDiscussions = discussions.filter((discussion) => {
    const matchesSearch =
      !searchQuery ||
      discussion.title.toLowerCase().includes(searchQuery.toLowerCase()) ||
      discussion.content.toLowerCase().includes(searchQuery.toLowerCase())

    const matchesCategory = selectedCategory === 'all' || discussion.category === selectedCategory

    return matchesSearch && matchesCategory
  })

  const filteredNotes = sharedNotes.filter((note) => {
    const matchesSearch =
      !searchQuery ||
      note.title.toLowerCase().includes(searchQuery.toLowerCase()) ||
      note.content.toLowerCase().includes(searchQuery.toLowerCase())

    return matchesSearch
  })

  const unreadNotifications = notifications.filter((n) => !n.isRead)

  if (isLoading) {
    return (
      <div className='flex min-h-screen items-center justify-center bg-gray-50'>
        <Card className='w-96'>
          <CardContent className='p-6 text-center'>
            <RefreshCw className='mx-auto mb-4 h-8 w-8 animate-spin text-blue-600' />
            <h3 className='mb-2 text-lg font-semibold'>Loading Collaboration Hub</h3>
            <p className='text-gray-600'>Setting up your collaborative workspace...</p>
          </CardContent>
        </Card>
      </div>
    )
  }

  return (
    <div className='min-h-screen bg-gray-50'>
      <div className='mx-auto max-w-7xl p-4'>
        {/* Header */}
        <div className='mb-6'>
          <div className='mb-4 flex items-center justify-between'>
            <div className='flex items-center gap-3'>
              <h1 className='text-3xl font-bold text-gray-900'>Collaboration Hub</h1>
              <Badge
                variant={isOnline ? 'default' : 'secondary'}
                className='flex items-center gap-1'
              >
                <div
                  className={`h-2 w-2 rounded-full ${isOnline ? 'bg-green-400' : 'bg-gray-400'}`}
                />
                {isOnline ? 'Online' : 'Offline'}
              </Badge>
            </div>

            <div className='flex items-center gap-2'>
              <Button variant='outline' size='sm' onClick={() => setActiveView('notifications')}>
                <Bell className='mr-2 h-4 w-4' />
                Notifications
                {unreadNotifications.length > 0 && (
                  <Badge variant='destructive' className='ml-2 px-1 py-0 text-xs'>
                    {unreadNotifications.length}
                  </Badge>
                )}
              </Button>
              <Button size='sm' onClick={() => setShowCreateGroupDialog(true)}>
                <Plus className='mr-2 h-4 w-4' />
                Create Group
              </Button>
            </div>
          </div>

          {error && (
            <div className='mb-4 rounded-lg border border-red-200 bg-red-50 p-4'>
              <div className='flex items-center gap-2'>
                <AlertCircle className='h-4 w-4 text-red-600' />
                <span className='text-red-800'>{error}</span>
              </div>
            </div>
          )}

          {/* Quick Stats */}
          <div className='mb-6 grid grid-cols-1 gap-4 md:grid-cols-4'>
            <Card>
              <CardContent className='p-4'>
                <div className='flex items-center gap-3'>
                  <div className='rounded-full bg-blue-100 p-2'>
                    <Users className='h-5 w-5 text-blue-600' />
                  </div>
                  <div>
                    <p className='text-sm font-medium text-gray-600'>Study Groups</p>
                    <p className='text-2xl font-bold text-gray-900'>{studyGroups.length}</p>
                  </div>
                </div>
              </CardContent>
            </Card>

            <Card>
              <CardContent className='p-4'>
                <div className='flex items-center gap-3'>
                  <div className='rounded-full bg-green-100 p-2'>
                    <MessageSquare className='h-5 w-5 text-green-600' />
                  </div>
                  <div>
                    <p className='text-sm font-medium text-gray-600'>Discussions</p>
                    <p className='text-2xl font-bold text-gray-900'>{discussions.length}</p>
                  </div>
                </div>
              </CardContent>
            </Card>

            <Card>
              <CardContent className='p-4'>
                <div className='flex items-center gap-3'>
                  <div className='rounded-full bg-yellow-100 p-2'>
                    <BookOpen className='h-5 w-5 text-yellow-600' />
                  </div>
                  <div>
                    <p className='text-sm font-medium text-gray-600'>Shared Notes</p>
                    <p className='text-2xl font-bold text-gray-900'>{sharedNotes.length}</p>
                  </div>
                </div>
              </CardContent>
            </Card>

            <Card>
              <CardContent className='p-4'>
                <div className='flex items-center gap-3'>
                  <div className='rounded-full bg-purple-100 p-2'>
                    <Activity className='h-5 w-5 text-purple-600' />
                  </div>
                  <div>
                    <p className='text-sm font-medium text-gray-600'>Online Members</p>
                    <p className='text-2xl font-bold text-gray-900'>{onlineMembers.size}</p>
                  </div>
                </div>
              </CardContent>
            </Card>
          </div>
        </div>

        <Tabs
          value={activeView}
          onValueChange={(value) => setActiveView(value as typeof activeView)}
          className='space-y-6'
        >
          <TabsList className='grid w-full grid-cols-4'>
            <TabsTrigger value='groups'>Study Groups</TabsTrigger>
            <TabsTrigger value='discussions'>Discussions</TabsTrigger>
            <TabsTrigger value='notes'>Shared Notes</TabsTrigger>
            <TabsTrigger value='notifications'>
              Notifications
              {unreadNotifications.length > 0 && (
                <Badge variant='destructive' className='ml-2 px-1 py-0 text-xs'>
                  {unreadNotifications.length}
                </Badge>
              )}
            </TabsTrigger>
          </TabsList>

          {/* Study Groups Tab */}
          <TabsContent value='groups' className='space-y-6'>
            <div className='flex items-center gap-4'>
              <div className='relative flex-1'>
                <Search className='absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 transform text-gray-400' />
                <Input
                  placeholder='Search study groups...'
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                  className='pl-10'
                />
              </div>

              <Select value={sortBy} onValueChange={(value) => setSortBy(value as typeof sortBy)}>
                <SelectTrigger className='w-48'>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value='recent'>Most Recent</SelectItem>
                  <SelectItem value='popular'>Most Popular</SelectItem>
                  <SelectItem value='alphabetical'>Alphabetical</SelectItem>
                </SelectContent>
              </Select>
            </div>

            <div className='grid grid-cols-1 gap-6 md:grid-cols-2 lg:grid-cols-3'>
              {filteredGroups.map((group) => (
                <Card key={group.id} className='transition-all duration-200 hover:shadow-lg'>
                  <CardHeader className='pb-3'>
                    <div className='flex items-start justify-between'>
                      <div className='flex items-center gap-3'>
                        <Avatar className='h-12 w-12'>
                          <AvatarImage src={group.avatar} />
                          <AvatarFallback>
                            {group.name.substring(0, 2).toUpperCase()}
                          </AvatarFallback>
                        </Avatar>
                        <div>
                          <CardTitle className='text-lg'>{group.name}</CardTitle>
                          <div className='mt-1 flex items-center gap-2'>
                            <Badge
                              variant={group.isPrivate ? 'secondary' : 'outline'}
                              className='text-xs'
                            >
                              {group.isPrivate ? 'Private' : 'Public'}
                            </Badge>
                            <Badge variant='outline' className='text-xs'>
                              {group.memberCount}/{group.maxMembers} members
                            </Badge>
                          </div>
                        </div>
                      </div>

                      <DropdownMenu>
                        <DropdownMenuTrigger asChild>
                          <Button variant='ghost' size='sm'>
                            <MoreHorizontal className='h-4 w-4' />
                          </Button>
                        </DropdownMenuTrigger>
                        <DropdownMenuContent align='end'>
                          <DropdownMenuItem onClick={() => handleSelectGroup(group)}>
                            <Eye className='mr-2 h-4 w-4' />
                            View Group
                          </DropdownMenuItem>
                          <DropdownMenuItem onClick={() => handleJoinGroup(group.id)}>
                            <UserPlus className='mr-2 h-4 w-4' />
                            Join Group
                          </DropdownMenuItem>
                          <DropdownMenuSeparator />
                          <DropdownMenuItem onClick={() => handleLeaveGroup(group.id)}>
                            <UserMinus className='mr-2 h-4 w-4' />
                            Leave Group
                          </DropdownMenuItem>
                        </DropdownMenuContent>
                      </DropdownMenu>
                    </div>
                  </CardHeader>

                  <CardContent>
                    <p className='mb-4 line-clamp-3 text-sm text-gray-600'>{group.description}</p>

                    <div className='mb-4 flex flex-wrap gap-1'>
                      {group.tags.slice(0, 3).map((tag) => (
                        <Badge key={tag} variant='outline' className='text-xs'>
                          {tag}
                        </Badge>
                      ))}
                      {group.tags.length > 3 && (
                        <Badge variant='outline' className='text-xs'>
                          +{group.tags.length - 3} more
                        </Badge>
                      )}
                    </div>

                    <div className='mb-4 flex items-center justify-between text-xs text-gray-500'>
                      <span>Created {formatDistanceToNow(group.createdAt)} ago</span>
                      <span>Active {formatDistanceToNow(group.lastActivity)} ago</span>
                    </div>

                    <Button
                      className='w-full'
                      onClick={() => handleSelectGroup(group)}
                      disabled={group.memberCount >= group.maxMembers}
                    >
                      <Users className='mr-2 h-4 w-4' />
                      {group.memberCount >= group.maxMembers ? 'Full' : 'Join & View'}
                    </Button>
                  </CardContent>
                </Card>
              ))}
            </div>
          </TabsContent>

          {/* Discussions Tab */}
          <TabsContent value='discussions' className='space-y-6'>
            {activeGroup ? (
              <>
                <div className='flex items-center justify-between'>
                  <div>
                    <h2 className='text-xl font-semibold text-gray-900'>
                      {activeGroup.name} Discussions
                    </h2>
                    <p className='text-gray-600'>{discussions.length} discussions</p>
                  </div>
                  <Button onClick={() => setShowCreateThreadDialog(true)}>
                    <Plus className='mr-2 h-4 w-4' />
                    New Discussion
                  </Button>
                </div>

                <div className='flex items-center gap-4'>
                  <div className='relative flex-1'>
                    <Search className='absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 transform text-gray-400' />
                    <Input
                      placeholder='Search discussions...'
                      value={searchQuery}
                      onChange={(e) => setSearchQuery(e.target.value)}
                      className='pl-10'
                    />
                  </div>

                  <Select value={selectedCategory} onValueChange={setSelectedCategory}>
                    <SelectTrigger className='w-48'>
                      <SelectValue placeholder='Category' />
                    </SelectTrigger>
                    <SelectContent>
                      <SelectItem value='all'>All Categories</SelectItem>
                      <SelectItem value='general'>General</SelectItem>
                      <SelectItem value='study'>Study</SelectItem>
                      <SelectItem value='exam'>Exam</SelectItem>
                      <SelectItem value='help'>Help</SelectItem>
                      <SelectItem value='resource'>Resource</SelectItem>
                    </SelectContent>
                  </Select>
                </div>

                <div className='space-y-3'>
                  {filteredDiscussions.map((thread) => (
                    <Card
                      key={thread.id}
                      className='cursor-pointer transition-shadow hover:shadow-md'
                      onClick={() => handleOpenThread(thread)}
                    >
                      <CardContent className='p-4'>
                        <div className='flex items-start justify-between'>
                          <div className='min-w-0 flex-1'>
                            <div className='mb-2 flex items-center gap-2'>
                              {thread.isPinned && <Pin className='h-4 w-4 text-blue-600' />}
                              <h3 className='truncate font-semibold text-gray-900'>
                                {thread.title}
                              </h3>
                              <Badge variant='outline' className='text-xs'>
                                {thread.category}
                              </Badge>
                              {thread.tags.slice(0, 2).map((tag) => (
                                <Badge key={tag} variant='secondary' className='text-xs'>
                                  {tag}
                                </Badge>
                              ))}
                            </div>

                            <p className='mb-3 line-clamp-2 text-sm text-gray-600'>
