export default EnhancedCollaborationHub

import React, { useState, useEffect } from 'react'
import {
  FileText,
  Plus,
  Heart,
  MessageSquare,
  Share2,
  Tag,
  User,
  Calendar,
  Eye,
  // Edit, // TODO: Use for editing
  Trash2,
  X,
} from 'lucide-react'
import collaborationService from '../../services/collaborationService'
import { useTheme } from '../../contexts/ThemeContext'

const SharedNotes = ({ processId = null, knowledgeArea = null }) => {
  const { settings } = useTheme()
  const [notes, setNotes] = useState([])
  const [showCreateForm, setShowCreateForm] = useState(false)
  const [selectedNote, setSelectedNote] = useState(null)
  const [filterTag, setFilterTag] = useState('')
  const [currentUser, setCurrentUser] = useState('')

  // 新規ノートのフォーム状態
  const [newNote, setNewNote] = useState({
    title: '',
    content: '',
    tags: '',
    isPublic: true,
  })

  // ノートの読み込み
  useEffect(() => {
    loadNotes()
    // ユーザー名の読み込み（簡易実装）
    const savedUser = localStorage.getItem('username') || 'Anonymous'
    setCurrentUser(savedUser)
  }, [processId, knowledgeArea, filterTag])

  const loadNotes = () => {
    const filters = {
      processId,
      knowledgeArea,
      tags: filterTag ? [filterTag] : [],
    }
    const loadedNotes = collaborationService.getNotes(filters)
    setNotes(loadedNotes)
  }

  // ノートの作成
  const handleCreateNote = () => {
    if (!newNote.title.trim() || !newNote.content.trim()) {
      alert('タイトルと内容を入力してください')
      return
    }

    const tags = newNote.tags
      .split(',')
      .map((tag) => tag.trim())
      .filter((tag) => tag.length > 0)

    const createdNote = collaborationService.createNote({
      ...newNote,
      tags,
      processId,
      knowledgeArea,
      author: currentUser,
    })

    setNotes([createdNote, ...notes])
    setNewNote({ title: '', content: '', tags: '', isPublic: true })
    setShowCreateForm(false)
  }

  // ノートのいいね
  const handleLikeNote = (noteId) => {
    collaborationService.likeNote(noteId)
    loadNotes()
  }

  // ノートの削除
  const handleDeleteNote = (noteId) => {
    if (confirm('このノートを削除しますか？')) {
      collaborationService.deleteNote(noteId)
      loadNotes()
      setSelectedNote(null)
    }
  }

  // 共有リンクの生成
  const handleShareNote = (note) => {
    const shareLink = collaborationService.generateShareLink({
      type: 'note',
      content: note,
    })

    // クリップボードにコピー
    navigator.clipboard.writeText(shareLink).then(() => {
      alert('共有リンクをクリップボードにコピーしました！')
    })
  }

  // タグの取得
  const getAllTags = () => {
    const allTags = new Set()
    notes.forEach((note) => {
      note.tags.forEach((tag) => allTags.add(tag))
    })
    return Array.from(allTags)
  }

  return (
    <div className={`p-4 ${settings.darkMode ? 'bg-gray-900 text-white' : 'bg-gray-50'}`}>
      {/* ヘッダー */}
      <div className='mb-6 flex items-center justify-between'>
        <h2 className='flex items-center gap-2 text-2xl font-bold'>
          <FileText className='h-6 w-6' />
          共有ノート
        </h2>
        <button
          onClick={() => setShowCreateForm(true)}
          className='flex items-center gap-2 rounded-lg bg-blue-600 px-4 py-2 text-white transition-colors hover:bg-blue-700'
        >
          <Plus className='h-4 w-4' />
          新規ノート
        </button>
      </div>

      {/* タグフィルター */}
      <div className='mb-4'>
        <div className='flex flex-wrap gap-2'>
          <button
            onClick={() => setFilterTag('')}
            className={`rounded-full px-3 py-1 text-sm transition-colors ${
              !filterTag
                ? 'bg-blue-600 text-white'
                : settings.darkMode
                  ? 'bg-gray-700 hover:bg-gray-600'
                  : 'bg-gray-200 hover:bg-gray-300'
            }`}
          >
            すべて
          </button>
          {getAllTags().map((tag) => (
            <button
              key={tag}
              onClick={() => setFilterTag(tag)}
              className={`rounded-full px-3 py-1 text-sm transition-colors ${
                filterTag === tag
                  ? 'bg-blue-600 text-white'
                  : settings.darkMode
                    ? 'bg-gray-700 hover:bg-gray-600'
                    : 'bg-gray-200 hover:bg-gray-300'
              }`}
            >
              <Tag className='mr-1 inline h-3 w-3' />
              {tag}
            </button>
          ))}
        </div>
      </div>

      {/* ノート一覧 */}
      <div className='grid grid-cols-1 gap-4 md:grid-cols-2 lg:grid-cols-3'>
