                    value={newNote.title}
                    onChange={(e) => setNewNote({ ...newNote, title: e.target.value })}
                    className={`w-full rounded-lg border px-3 py-2 ${
                      settings.darkMode ? 'border-gray-600 bg-gray-700' : 'border-gray-300 bg-white'
                    }`}
                    placeholder='ノートのタイトル'
                  />
