  const profileButtonRef = React.useRef(null)
  const profileMenuRef = React.useRef(null)

  // Generate breadcrumbs based on current path
  const generateBreadcrumbs = (pathname) => {
    const breadcrumbs = [{ path: '/', label: 'ホーム' }]
