  Zap,
  RefreshCw,
} from 'lucide-react'
import {
  useFlashCardStore,
  // type FlashCard,
  // type FlashCardDeck,
  // type _StudySession,
} from '../../stores/flashcardStore'
import { useToast } from '../../hooks/use-toast'
import { Card, CardContent, CardHeader, CardTitle } from '../ui/card'
import { Button } from '../ui/button'
import { Progress } from '../ui/progress'
