  Database,
  Activity,
  Eye,
  Copy,
  Share2,
  Flag,
  ThumbsUp,
  ThumbsDown,
} from 'lucide-react'
import promptLogService from '../../services/promptLogService'
import { useToast } from '../ui/use-toast'
import { format, formatDistanceToNow } from 'date-fns'

const PromptLogDashboard = () => {
  const { toast } = useToast()
  const [logs, setLogs] = useState([])
  const [statistics, setStatistics] = useState(null)
  const [loading, setLoading] = useState(true)
  const [selectedLog, setSelectedLog] = useState(null)
  const [filters, setFilters] = useState({
    type: 'all',
    userId: '',
    sessionId: '',
    status: 'all',
    timeRange: '24h',
    searchQuery: '',
    tags: [],
  })
  const [currentPage, setCurrentPage] = useState(1)
  // //   const [pageSize, setPageSize] = useState(50) // TODO: Will be used in future // TODO: Will be used in future
  const [sortConfig, setSortConfig] = useState({ field: 'timestamp', order: 'desc' })
  const [exportFormat, setExportFormat] = useState('json')
  const [config, setConfig] = useState(promptLogService.getConfig())
  const [isConfigOpen, setIsConfigOpen] = useState(false)
  // //   const [refreshInterval, setRefreshInterval] = useState(null) // TODO: Will be used in future // TODO: Will be used in future

  // Load initial data
  useEffect(() => {
    loadLogs()
    loadStatistics()

    // Set up auto-refresh if enabled
    if (config.autoRefresh) {
      const interval = setInterval(() => {
        loadLogs()
        loadStatistics()
      }, 30000) // Refresh every 30 seconds
      setRefreshInterval(interval)

      return () => clearInterval(interval)
    }
  }, [])

  // Load logs with current filters
  const loadLogs = useCallback(async () => {
    setLoading(true)
    try {
      const timeRange = getTimeRange(filters.timeRange)
      const result = await promptLogService.queryLogs({
        ...filters,
        startTime: timeRange.start,
        endTime: timeRange.end,
        sort: sortConfig,
        page: currentPage,
        limit: pageSize,
      })
      setLogs(result)
    } catch (error) {
      console.error('Failed to load logs:', error)
      toast({
        title: 'Error loading logs',
        description: error.message,
        variant: 'destructive',
      })
    } finally {
      setLoading(false)
    }
  }, [filters, sortConfig, currentPage, pageSize])

  // Load statistics
  const loadStatistics = useCallback(async () => {
    try {
      const timeRange = getTimeRange(filters.timeRange)
      const stats = await promptLogService.getStatistics(timeRange)
      setStatistics(stats)
    } catch (error) {
      console.error('Failed to load statistics:', error)
    }
  }, [filters.timeRange])

  // Effect to reload logs when filters change
  useEffect(() => {
    loadLogs()
  }, [loadLogs])

  // Effect to reload statistics when time range changes
  useEffect(() => {
    loadStatistics()
  }, [loadStatistics])

  // Get time range based on filter
  const getTimeRange = (range) => {
    const now = Date.now()
    switch (range) {
      case '1h':
        return { start: now - 3600000, end: now }
      case '24h':
        return { start: now - 86400000, end: now }
      case '7d':
        return { start: now - 604800000, end: now }
      case '30d':
        return { start: now - 2592000000, end: now }
      case 'all':
        return { start: 0, end: now }
      default:
        return { start: now - 86400000, end: now }
    }
  }

  // Handle log export
  const handleExport = async () => {
    try {
      const exportData = await promptLogService.exportLogs(exportFormat, filters)
      const blob = new Blob([exportData], { type: getMimeType(exportFormat) })
      const url = URL.createObjectURL(blob)
      const a = document.createElement('a')
      a.href = url
      a.download = `prompt-logs-${Date.now()}.${exportFormat}`
      document.body.appendChild(a)
      a.click()
      document.body.removeChild(a)
      URL.revokeObjectURL(url)

      toast({
        title: 'Export successful',
        description: `Logs exported as ${exportFormat.toUpperCase()}`,
      })
    } catch (error) {
      toast({
        title: 'Export failed',
        description: error.message,
        variant: 'destructive',
      })
    }
  }

  // Get MIME type for export format
  const getMimeType = (format) => {
    const types = {
      json: 'application/json',
      jsonl: 'application/x-ndjson',
      csv: 'text/csv',
      markdown: 'text/markdown',
    }
    return types[format] || 'text/plain'
  }

  // Handle clear all logs
  const handleClearAll = async () => {
    if (window.confirm('Are you sure you want to clear all logs? This action cannot be undone.')) {
      try {
        await promptLogService.clearAllLogs()
        setLogs([])
        setStatistics(null)
        toast({
          title: 'Logs cleared',
          description: 'All logs have been permanently deleted',
        })
      } catch (error) {
        toast({
          title: 'Clear failed',
          description: error.message,
          variant: 'destructive',
        })
      }
    }
  }

  // Handle config update
  const handleConfigUpdate = async (newConfig) => {
    try {
      promptLogService.updateConfig(newConfig)
      setConfig(newConfig)
      toast({
        title: 'Configuration updated',
        description: 'Settings have been saved',
      })
    } catch (error) {
      toast({
        title: 'Update failed',
        description: error.message,
        variant: 'destructive',
      })
    }
  }

  // Handle sort
  const handleSort = (field) => {
    setSortConfig((prev) => ({
      field,
      order: prev.field === field && prev.order === 'asc' ? 'desc' : 'asc',
    }))
  }

  // Format timestamp
  const formatTimestamp = (timestamp) => {
    return format(new Date(timestamp), 'yyyy-MM-dd HH:mm:ss')
  }

  // Format relative time
  const formatRelativeTime = (timestamp) => {
    return formatDistanceToNow(new Date(timestamp), { addSuffix: true })
  }

  // Get status color
  const getStatusColor = (status) => {
    const colors = {
      completed: 'bg-green-500',
      pending: 'bg-yellow-500',
      error: 'bg-red-500',
      processing: 'bg-blue-500',
    }
    return colors[status] || 'bg-gray-500'
  }

  // Get type icon
  const getTypeIcon = (type) => {
    const icons = {
      prompt: <MessageSquare className='h-4 w-4' />,
      response: <Bot className='h-4 w-4' />,
      interaction: <User className='h-4 w-4' />,
    }
    return icons[type] || <FileText className='h-4 w-4' />
  }

  // Prepare chart data
  const chartData = useMemo(() => {
    if (!statistics) {
      return {}
    }

    // Activity over time
    const activityData = logs.data?.reduce((acc, log) => {
      const date = format(new Date(log.timestamp), 'yyyy-MM-dd')
      if (!acc[date]) {
        acc[date] = { date, prompts: 0, responses: 0, interactions: 0 }
      }
      acc[date][`${log.type}s`]++
      return acc
    }, {})

    // Cost by model
    const costData = Object.entries(statistics.costAnalysis?.costByModel || {}).map(
      ([model, data]) => ({
        model,
        cost: data.total,
        count: data.count,
      })
    )

    // Top tags
    const tagData = statistics.topTags || []

    return {
      activity: Object.values(activityData || {}),
      cost: costData,
      tags: tagData,
    }
  }, [statistics, logs])

  return (
    <div className='container mx-auto space-y-6 p-6'>
      {/* Header */}
      <div className='flex items-center justify-between'>
        <div>
          <h1 className='text-3xl font-bold'>Prompt Log Dashboard</h1>
          <p className='text-muted-foreground'>Monitor and analyze AI prompt interactions</p>
        </div>
        <div className='flex gap-2'>
          <Button onClick={loadLogs} variant='outline' size='sm'>
            <RefreshCw className='mr-2 h-4 w-4' />
            Refresh
          </Button>
