import React, { useState, useMemo } from 'react'
import { Search, Filter, ChevronDown, ChevronRight, BookOpen, Eye } from 'lucide-react'
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Badge } from '@/components/ui/badge'
import { Collapsible, CollapsibleContent, CollapsibleTrigger } from '@/components/ui/collapsible'
import { Sheet, SheetContent, SheetHeader, SheetTitle, SheetTrigger } from '@/components/ui/sheet'
import { Checkbox } from '@/components/ui/checkbox'
import { useHapticFeedback } from '@/hooks/useTouchGestures'

interface Process {
  id: string
  name: string
  knowledgeArea: string
  processGroup: string
  inputs: string[]
  tools: string[]
  outputs: string[]
  description?: string
}

interface MobilePMBOKMatrixProps {
  processes: Process[]
  onProcessSelect?: (process: Process) => void
}

const knowledgeAreas = [
  '統合管理',
  'スコープ管理',
  'スケジュール管理',
  'コスト管理',
  '品質管理',
  '資源管理',
  'コミュニケーション管理',
  'リスク管理',
  '調達管理',
  'ステークホルダー管理',
]

const processGroups = ['立ち上げ', '計画', '実行', '監視・コントロール', '終結']

export function MobilePMBOKMatrix({ processes, onProcessSelect }: MobilePMBOKMatrixProps) {
  const [searchQuery, setSearchQuery] = useState('')
  const [selectedKnowledgeAreas, setSelectedKnowledgeAreas] = useState<string[]>(knowledgeAreas)
  const [selectedProcessGroups, setSelectedProcessGroups] = useState<string[]>(processGroups)
  const [expandedKnowledgeAreas, setExpandedKnowledgeAreas] = useState<Set<string>>(new Set())
  const [showFilters, setShowFilters] = useState(false)
  const [selectedProcess, setSelectedProcess] = useState<Process | null>(null)
  const haptic = useHapticFeedback()

  const filteredProcesses = useMemo(() => {
    return processes.filter((process) => {
      const matchesSearch =
        process.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
        process.description?.toLowerCase().includes(searchQuery.toLowerCase())
      const matchesKnowledgeArea = selectedKnowledgeAreas.includes(process.knowledgeArea)
      const matchesProcessGroup = selectedProcessGroups.includes(process.processGroup)

      return matchesSearch && matchesKnowledgeArea && matchesProcessGroup
    })
  }, [processes, searchQuery, selectedKnowledgeAreas, selectedProcessGroups])

  const groupedProcesses = useMemo(() => {
    const grouped: Record<string, Process[]> = {}

    filteredProcesses.forEach((process) => {
      if (!grouped[process.knowledgeArea]) {
        grouped[process.knowledgeArea] = []
      }
      grouped[process.knowledgeArea].push(process)
    })

    return grouped
  }, [filteredProcesses])

  const toggleKnowledgeArea = (area: string) => {
    setExpandedKnowledgeAreas((prev) => {
      const newSet = new Set(prev)
      if (newSet.has(area)) {
        newSet.delete(area)
      } else {
        newSet.add(area)
      }
      haptic.light()
      return newSet
    })
  }

  const handleProcessSelect = (process: Process) => {
    setSelectedProcess(process)
    onProcessSelect?.(process)
    haptic.medium()
  }

  const handleFilterChange = (
    type: 'knowledgeArea' | 'processGroup',
    value: string,
    checked: boolean
  ) => {
    if (type === 'knowledgeArea') {
      setSelectedKnowledgeAreas((prev) =>
        checked ? [...prev, value] : prev.filter((item) => item !== value)
      )
    } else {
      setSelectedProcessGroups((prev) =>
        checked ? [...prev, value] : prev.filter((item) => item !== value)
      )
    }
    haptic.light()
  }

  const getProcessGroupColor = (processGroup: string) => {
    const colors = {
      立ち上げ: 'bg-blue-100 text-blue-700 dark:bg-blue-900/20 dark:text-blue-400',
      計画: 'bg-green-100 text-green-700 dark:bg-green-900/20 dark:text-green-400',
      実行: 'bg-orange-100 text-orange-700 dark:bg-orange-900/20 dark:text-orange-400',
      '監視・コントロール':
        'bg-purple-100 text-purple-700 dark:bg-purple-900/20 dark:text-purple-400',
      終結: 'bg-gray-100 text-gray-700 dark:bg-gray-900/20 dark:text-gray-400',
    }
    return colors[processGroup as keyof typeof colors] || colors['計画']
  }

  return (
    <div className='flex h-full flex-col'>
      {/* Search and Filter Bar */}
      <div className='space-y-3 border-b border-gray-200 bg-white p-4 dark:border-gray-700 dark:bg-gray-800'>
        <div className='flex items-center space-x-2'>
          <div className='relative flex-1'>
            <Search className='absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 transform text-gray-400' />
            <Input
              placeholder='プロセスを検索...'
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className='pl-10'
            />
          </div>

          <Sheet open={showFilters} onOpenChange={setShowFilters}>
            <SheetTrigger asChild>
              <Button variant='outline' size='icon'>
                <Filter className='h-4 w-4' />
              </Button>
            </SheetTrigger>
            <SheetContent side='right' className='w-[280px]'>
              <SheetHeader>
                <SheetTitle>フィルター</SheetTitle>
              </SheetHeader>

              <div className='mt-6 space-y-6'>
                <div>
                  <h3 className='mb-3 font-medium'>知識エリア</h3>
                  <div className='space-y-2'>
                    {knowledgeAreas.map((area) => (
                      <div key={area} className='flex items-center space-x-2'>
                        <Checkbox
                          id={`ka-${area}`}
                          checked={selectedKnowledgeAreas.includes(area)}
                          onCheckedChange={(checked) =>
                            handleFilterChange('knowledgeArea', area, checked as boolean)
                          }
                        />
                        <label
                          htmlFor={`ka-${area}`}
                          className='text-sm font-medium leading-none peer-disabled:cursor-not-allowed peer-disabled:opacity-70'
                        >
                          {area}
                        </label>
                      </div>
                    ))}
                  </div>
                </div>

                <div>
                  <h3 className='mb-3 font-medium'>プロセス群</h3>
                  <div className='space-y-2'>
                    {processGroups.map((group) => (
                      <div key={group} className='flex items-center space-x-2'>
                        <Checkbox
                          id={`pg-${group}`}
                          checked={selectedProcessGroups.includes(group)}
                          onCheckedChange={(checked) =>
                            handleFilterChange('processGroup', group, checked as boolean)
                          }
                        />
                        <label
                          htmlFor={`pg-${group}`}
                          className='text-sm font-medium leading-none peer-disabled:cursor-not-allowed peer-disabled:opacity-70'
                        >
                          {group}
                        </label>
                      </div>
                    ))}
                  </div>
                </div>
              </div>
            </SheetContent>
          </Sheet>
        </div>

        <div className='flex items-center justify-between text-sm text-gray-600 dark:text-gray-400'>
          <span>{filteredProcesses.length} プロセスが見つかりました</span>
          {(selectedKnowledgeAreas.length < knowledgeAreas.length ||
            selectedProcessGroups.length < processGroups.length) && (
            <Button
              variant='ghost'
              size='sm'
              onClick={() => {
                setSelectedKnowledgeAreas(knowledgeAreas)
                setSelectedProcessGroups(processGroups)
              }}
            >
              フィルターをリセット
            </Button>
          )}
        </div>
      </div>

      {/* Process List */}
      <div className='flex-1 space-y-4 overflow-y-auto px-4 py-4'>
        {knowledgeAreas.map((area) => {
          const areaProcesses = groupedProcesses[area] || []
          if (areaProcesses.length === 0) {
            return null
          }

          return (
            <Card key={area}>
              <Collapsible
                open={expandedKnowledgeAreas.has(area)}
                onOpenChange={() => toggleKnowledgeArea(area)}
              >
                <CollapsibleTrigger asChild>
                  <CardHeader className='cursor-pointer transition-colors hover:bg-gray-50 dark:hover:bg-gray-800/50'>
                    <div className='flex items-center justify-between'>
                      <CardTitle className='text-base'>{area}</CardTitle>
                      <div className='flex items-center space-x-2'>
                        <Badge variant='secondary' className='text-xs'>
                          {areaProcesses.length}
                        </Badge>
                        {expandedKnowledgeAreas.has(area) ? (
                          <ChevronDown className='h-4 w-4' />
                        ) : (
                          <ChevronRight className='h-4 w-4' />
                        )}
                      </div>
                    </div>
                  </CardHeader>
                </CollapsibleTrigger>

                <CollapsibleContent>
                  <CardContent className='space-y-3 pt-0'>
                    {areaProcesses.map((process) => (
                      <div
                        key={process.id}
                        className='cursor-pointer rounded-lg border border-gray-200 p-3 transition-colors hover:bg-gray-50 dark:border-gray-700 dark:hover:bg-gray-800/50'
                        onClick={() => handleProcessSelect(process)}
                      >
                        <div className='mb-2 flex items-start justify-between'>
                          <h4 className='flex-1 text-sm font-medium leading-relaxed text-gray-900 dark:text-gray-100'>
                            {process.name}
                          </h4>
                          <Button
                            variant='ghost'
                            size='icon'
                            className='ml-2 h-6 w-6 flex-shrink-0'
                          >
                            <Eye className='h-3 w-3' />
                          </Button>
                        </div>

                        <Badge
                          className={`text-xs ${getProcessGroupColor(process.processGroup)}`}
                          variant='secondary'
                        >
                          {process.processGroup}
                        </Badge>

                        <div className='mt-2 flex items-center justify-between text-xs text-gray-500 dark:text-gray-400'>
                          <span>
                            I:{process.inputs.length} T:{process.tools.length} O:
                            {process.outputs.length}
                          </span>
                          <BookOpen className='h-3 w-3' />
                        </div>
                      </div>
                    ))}
                  </CardContent>
                </CollapsibleContent>
              </Collapsible>
            </Card>
          )
        })}
      </div>

      {/* Process Detail Sheet */}
      <Sheet open={!!selectedProcess} onOpenChange={() => setSelectedProcess(null)}>
        <SheetContent side='bottom' className='h-[80vh]'>
          {selectedProcess && (
            <>
              <SheetHeader>
                <SheetTitle className='text-left'>{selectedProcess.name}</SheetTitle>
              </SheetHeader>

              <div className='mt-6 space-y-6 overflow-y-auto'>
                <div className='flex flex-wrap gap-2'>
                  <Badge variant='outline'>{selectedProcess.knowledgeArea}</Badge>
                  <Badge
                    className={getProcessGroupColor(selectedProcess.processGroup)}
                    variant='secondary'
                  >
                    {selectedProcess.processGroup}
                  </Badge>
                </div>

                {selectedProcess.description && (
                  <div>
                    <h3 className='mb-2 font-medium'>概要</h3>
                    <p className='text-sm leading-relaxed text-gray-600 dark:text-gray-400'>
                      {selectedProcess.description}
                    </p>
                  </div>
                )}

                <div>
                  <h3 className='mb-2 font-medium text-blue-600 dark:text-blue-400'>
                    インプット ({selectedProcess.inputs.length})
                  </h3>
                  <div className='space-y-1'>
                    {selectedProcess.inputs.map((input, idx) => (
                      <div
                        key={idx}
                        className='flex items-start text-sm text-gray-700 dark:text-gray-300'
                      >
                        <span className='mr-2 text-blue-600 dark:text-blue-400'>•</span>
                        <span className='flex-1'>{input}</span>
                      </div>
                    ))}
                  </div>
                </div>

                <div>
                  <h3 className='mb-2 font-medium text-green-600 dark:text-green-400'>
                    ツールと技法 ({selectedProcess.tools.length})
                  </h3>
                  <div className='space-y-1'>
                    {selectedProcess.tools.map((tool, idx) => (
                      <div
                        key={idx}
                        className='flex items-start text-sm text-gray-700 dark:text-gray-300'
                      >
                        <span className='mr-2 text-green-600 dark:text-green-400'>•</span>
                        <span className='flex-1'>{tool}</span>
                      </div>
                    ))}
                  </div>
                </div>

                <div>
                  <h3 className='mb-2 font-medium text-purple-600 dark:text-purple-400'>
                    アウトプット ({selectedProcess.outputs.length})
                  </h3>
                  <div className='space-y-1'>
                    {selectedProcess.outputs.map((output, idx) => (
                      <div
                        key={idx}
                        className='flex items-start text-sm text-gray-700 dark:text-gray-300'
                      >
                        <span className='mr-2 text-purple-600 dark:text-purple-400'>•</span>
                        <span className='flex-1'>{output}</span>
                      </div>
                    ))}
                  </div>
                </div>
              </div>
            </>
          )}
        </SheetContent>
      </Sheet>
    </div>
  )
}

export default MobilePMBOKMatrix

import React, { useState, useRef, useEffect } from 'react'
import { ChevronDown, ChevronUp, Star, Heart, Share2, Bookmark } from 'lucide-react'

// Touch-friendly button with haptic feedback
export const TouchButton = ({
  children,
  onClick,
  variant = 'primary',
  size = 'md',
  disabled = false,
  haptic = true,
  className = '',
  ...props
}) => {
  const [isPressed, setIsPressed] = useState(false)

  const handleTouchStart = () => {
    setIsPressed(true)
    if (haptic && navigator.vibrate && !disabled) {
      navigator.vibrate(10)
    }
  }

  const handleTouchEnd = () => {
    setIsPressed(false)
  }

  const baseClasses = `
    relative overflow-hidden transition-all duration-150 rounded-xl font-medium
    active:scale-95 select-none touch-manipulation
    ${disabled ? 'opacity-50 cursor-not-allowed' : 'cursor-pointer'}
    ${isPressed ? 'scale-95' : ''}
  `

  const variantClasses = {
    primary: 'bg-blue-500 hover:bg-blue-600 text-white shadow-lg',
    secondary:
      'bg-gray-200 dark:bg-gray-700 hover:bg-gray-300 dark:hover:bg-gray-600 text-gray-900 dark:text-white',
    outline: 'border-2 border-blue-500 text-blue-500 hover:bg-blue-50 dark:hover:bg-blue-900/20',
    ghost: 'text-gray-700 dark:text-gray-300 hover:bg-gray-100 dark:hover:bg-gray-800',
  }

  const sizeClasses = {
    sm: 'px-4 py-2 text-sm min-h-[40px]',
    md: 'px-6 py-3 text-base min-h-[48px]',
    lg: 'px-8 py-4 text-lg min-h-[56px]',
  }

  return (
    <button
      className={`${baseClasses} ${variantClasses[variant]} ${sizeClasses[size]} ${className}`}
      onTouchStart={handleTouchStart}
      onTouchEnd={handleTouchEnd}
      onMouseLeave={() => setIsPressed(false)}
      onClick={disabled ? undefined : onClick}
      disabled={disabled}
      {...props}
    >
      {children}
    </button>
  )
}

// Expandable card with touch gestures
export const TouchExpandableCard = ({ title, children, defaultExpanded = false }) => {
  const [isExpanded, setIsExpanded] = useState(defaultExpanded)
  const [startY, setStartY] = useState(0)
  const [currentY, setCurrentY] = useState(0)
  const cardRef = useRef(null)

  const handleTouchStart = (e) => {
    setStartY(e.touches[0].clientY)
  }

  const handleTouchMove = (e) => {
    setCurrentY(e.touches[0].clientY)
  }

  const handleTouchEnd = () => {
    const deltaY = currentY - startY

    if (Math.abs(deltaY) > 50) {
      if (deltaY < 0 && !isExpanded) {
        // Swipe up to expand
        setIsExpanded(true)
        if (navigator.vibrate) {
          navigator.vibrate(15)
        }
      } else if (deltaY > 0 && isExpanded) {
        // Swipe down to collapse
        setIsExpanded(false)
        if (navigator.vibrate) {
          navigator.vibrate(15)
        }
      }
    }

    setStartY(0)
    setCurrentY(0)
  }

  return (
    <div
      ref={cardRef}
      className='overflow-hidden rounded-xl border bg-white shadow-lg dark:border-gray-700 dark:bg-gray-800'
    >
      <div
        className='cursor-pointer touch-manipulation select-none p-4 active:bg-gray-50 dark:active:bg-gray-700'
        onTouchStart={handleTouchStart}
        onTouchMove={handleTouchMove}
        onTouchEnd={handleTouchEnd}
        onClick={() => setIsExpanded(!isExpanded)}
      >
        <div className='flex items-center justify-between'>
          <h3 className='text-lg font-semibold text-gray-900 dark:text-white'>{title}</h3>
          <div className='flex items-center gap-2'>
            {isExpanded ? <ChevronUp className='h-5 w-5' /> : <ChevronDown className='h-5 w-5' />}
          </div>
        </div>

        {/* Swipe indicator */}
        <div className='mt-2 flex justify-center'>
          <div className='h-1 w-12 rounded-full bg-gray-300 dark:bg-gray-600' />
        </div>
      </div>

      {/* Expandable content */}
      <div
        className={`
          overflow-hidden transition-all duration-300 ease-in-out
          ${isExpanded ? 'max-h-96 opacity-100' : 'max-h-0 opacity-0'}
        `}
      >
        <div className='border-t p-4 pt-0 dark:border-gray-700'>{children}</div>
      </div>
    </div>
  )
}

// Touch-friendly action bar
export const TouchActionBar = ({ items = [], onAction }) => {
  const [activeItem, setActiveItem] = useState(null)

  const defaultItems = [
    { id: 'favorite', icon: Heart, label: 'お気に入り', color: 'text-red-500' },
    { id: 'bookmark', icon: Bookmark, label: 'ブックマーク', color: 'text-blue-500' },
    { id: 'share', icon: Share2, label: '共有', color: 'text-green-500' },
    { id: 'star', icon: Star, label: '評価', color: 'text-yellow-500' },
  ]

  const actionItems = items.length > 0 ? items : defaultItems

  const handleAction = (item) => {
    setActiveItem(item.id)
    if (navigator.vibrate) {
      navigator.vibrate(20)
    }

    // Reset active state after animation
    setTimeout(() => setActiveItem(null), 200)

    if (onAction) {
      onAction(item)
    }
  }

  return (
    <div className='border-t bg-white p-4 dark:border-gray-700 dark:bg-gray-800'>
      <div className='flex items-center justify-around'>
        {actionItems.map((item) => {
          const Icon = item.icon
          const isActive = activeItem === item.id

          return (
            <button
              key={item.id}
              onClick={() => handleAction(item)}
              className={`
                flex min-w-[60px] touch-manipulation flex-col items-center gap-2 rounded-xl p-3
                transition-all duration-150
                ${
                  isActive
                    ? 'scale-110 bg-gray-100 dark:bg-gray-700'
                    : 'hover:bg-gray-50 active:scale-95 dark:hover:bg-gray-700/50'
                }
              `}
            >
              <Icon className={`h-6 w-6 ${item.color || 'text-gray-600 dark:text-gray-400'}`} />
              <span className='text-xs font-medium text-gray-600 dark:text-gray-400'>
                {item.label}
              </span>
            </button>
          )
        })}
      </div>
    </div>
  )
}

// Long press menu component
export const TouchLongPressMenu = ({ children, menuItems = [], onMenuAction }) => {
  const [showMenu, setShowMenu] = useState(false)
  const [menuPosition, setMenuPosition] = useState({ x: 0, y: 0 })
  const longPressTimer = useRef(null)
  const startPos = useRef({ x: 0, y: 0 })

  const handleTouchStart = (e) => {
    const touch = e.touches[0]
    startPos.current = { x: touch.clientX, y: touch.clientY }

    longPressTimer.current = setTimeout(() => {
      setMenuPosition({ x: touch.clientX, y: touch.clientY })
      setShowMenu(true)
      if (navigator.vibrate) {
        navigator.vibrate(50)
      }
    }, 500)
  }

  const handleTouchMove = (e) => {
    const touch = e.touches[0]
    const deltaX = Math.abs(touch.clientX - startPos.current.x)
    const deltaY = Math.abs(touch.clientY - startPos.current.y)

    // Cancel long press if user moves finger too much
    if (deltaX > 10 || deltaY > 10) {
      if (longPressTimer.current) {
        clearTimeout(longPressTimer.current)
        longPressTimer.current = null
      }
    }
  }

  const handleTouchEnd = () => {
    if (longPressTimer.current) {
      clearTimeout(longPressTimer.current)
      longPressTimer.current = null
    }
  }

  const handleMenuAction = (item) => {
    setShowMenu(false)
    if (onMenuAction) {
      onMenuAction(item)
    }
  }

  useEffect(() => {
    const handleClickOutside = () => setShowMenu(false)
    if (showMenu) {
      document.addEventListener('click', handleClickOutside)
      return () => document.removeEventListener('click', handleClickOutside)
    }
  }, [showMenu])

  return (
    <>
      <div
        onTouchStart={handleTouchStart}
        onTouchMove={handleTouchMove}
        onTouchEnd={handleTouchEnd}
        className='touch-manipulation'
      >
        {children}
      </div>

      {showMenu && (
        <div
          className='fixed z-50 min-w-[160px] rounded-xl border bg-white py-2 shadow-2xl dark:border-gray-700 dark:bg-gray-800'
          style={{
            left: Math.min(menuPosition.x, window.innerWidth - 180),
            top: Math.min(menuPosition.y, window.innerHeight - menuItems.length * 48 - 20),
          }}
        >
          {menuItems.map((item, index) => {
            const Icon = item.icon
            return (
              <button
                key={index}
                onClick={() => handleMenuAction(item)}
                className='flex w-full items-center gap-3 px-4 py-3 text-left transition-colors hover:bg-gray-50 dark:hover:bg-gray-700'
              >
                {Icon && <Icon className='h-4 w-4' />}
                <span className='text-sm font-medium'>{item.label}</span>
              </button>
            )
          })}
        </div>
      )}
    </>
  )
}

// Swipeable list item
export const SwipeableListItem = ({ children, leftActions = [], rightActions = [], onSwipe }) => {
  const [swipeOffset, setSwipeOffset] = useState(0)
  const [isSwipping, setIsSwiping] = useState(false)
  const startX = useRef(0)
  const currentX = useRef(0)
  const itemRef = useRef(null)

  const handleTouchStart = (e) => {
    startX.current = e.touches[0].clientX
    setIsSwiping(true)
  }

  const handleTouchMove = (e) => {
    if (!isSwipping) {
      return
    }

    currentX.current = e.touches[0].clientX
    const deltaX = currentX.current - startX.current
    const maxOffset = 80

    setSwipeOffset(Math.max(-maxOffset, Math.min(maxOffset, deltaX)))
  }

  const handleTouchEnd = () => {
    setIsSwiping(false)

    if (Math.abs(swipeOffset) > 40) {
      const direction = swipeOffset > 0 ? 'right' : 'left'
      const actions = direction === 'right' ? rightActions : leftActions

      if (actions.length > 0 && onSwipe) {
        onSwipe(direction, actions[0])
      }
    }

    // Reset position
    setTimeout(() => setSwipeOffset(0), 100)
  }

  return (
    <div className='relative overflow-hidden'>
      {/* Left actions */}
      {leftActions.length > 0 && (
        <div className='absolute bottom-0 left-0 top-0 flex items-center bg-green-500 px-4 text-white'>
          {leftActions.map((action, index) => {
            const Icon = action.icon
            return (
              <div key={index} className='flex flex-col items-center'>
                {Icon && <Icon className='h-5 w-5' />}
                <span className='mt-1 text-xs'>{action.label}</span>
              </div>
            )
          })}
        </div>
      )}

      {/* Right actions */}
      {rightActions.length > 0 && (
        <div className='absolute bottom-0 right-0 top-0 flex items-center bg-red-500 px-4 text-white'>
          {rightActions.map((action, index) => {
            const Icon = action.icon
            return (
              <div key={index} className='flex flex-col items-center'>
                {Icon && <Icon className='h-5 w-5' />}
                <span className='mt-1 text-xs'>{action.label}</span>
              </div>
            )
          })}
        </div>
      )}

      {/* Main content */}
      <div
        ref={itemRef}
        className='touch-manipulation bg-white transition-transform duration-200 ease-out dark:bg-gray-800'
        style={{ transform: `translateX(${swipeOffset}px)` }}
        onTouchStart={handleTouchStart}
        onTouchMove={handleTouchMove}
        onTouchEnd={handleTouchEnd}
      >
        {children}
      </div>
    </div>
  )
}

/**
 * @file OfflineIndicator.tsx
 * @description オフライン状態を表示するインジケーターコンポーネント
 * @author Developer 6 (mobile-app-developer) - PWA/モバイル開発
 * @created 2025-08-30
 */

import React, { useEffect, useState } from 'react'
import { WifiOff, Wifi, CloudOff, RefreshCw } from 'lucide-react'
import { cn } from '@/lib/utils'

interface OfflineIndicatorProps {
  className?: string
  showDetails?: boolean
}

export function OfflineIndicator({ className, showDetails = false }: OfflineIndicatorProps) {
  const [isOnline, setIsOnline] = useState(navigator.onLine)
  const [syncPending, setSyncPending] = useState(false)
  const [lastSyncTime, setLastSyncTime] = useState<Date | null>(null)

  useEffect(() => {
    const handleOnline = () => {
      setIsOnline(true)
      // Trigger background sync when coming online
      if ('serviceWorker' in navigator && 'sync' in ServiceWorkerRegistration.prototype) {
        navigator.serviceWorker.ready.then((registration: ServiceWorkerRegistration) => {
          // @ts-ignore - sync is not in TypeScript types yet
          registration.sync.register('offline-queue')
        })
      }
    }

    const handleOffline = () => {
      setIsOnline(false)
      setSyncPending(true)
    }

    // Service Worker message handler
    const handleMessage = (event: MessageEvent) => {
      if (event.data && event.data.type === 'SYNC_COMPLETE') {
        setSyncPending(false)
        setLastSyncTime(new Date(event.data.data.timestamp))
      }
    }

    window.addEventListener('online', handleOnline)
    window.addEventListener('offline', handleOffline)

    if ('serviceWorker' in navigator) {
      navigator.serviceWorker.addEventListener('message', handleMessage)
    }

    // Check connection quality
    const checkConnection = () => {
      // @ts-ignore - connection is not standard yet
      const connection =
        navigator.connection || navigator.mozConnection || navigator.webkitConnection
      if (connection) {
        // Check for slow connections
        if (connection.effectiveType === '2g' || connection.effectiveType === 'slow-2g') {
          console.warn('Slow connection detected:', connection.effectiveType)
        }
      }
    }

    checkConnection()
    const interval = setInterval(checkConnection, 30000) // Check every 30 seconds

    return () => {
      window.removeEventListener('online', handleOnline)
      window.removeEventListener('offline', handleOffline)
      if ('serviceWorker' in navigator) {
        navigator.serviceWorker.removeEventListener('message', handleMessage)
      }
      clearInterval(interval)
    }
  }, [])

  if (isOnline && !syncPending && !showDetails) {
    return null // Don't show indicator when online and no sync pending
  }

  return (
    <div
      className={cn(
        'fixed bottom-20 left-4 z-50 flex items-center gap-2 rounded-lg px-3 py-2 shadow-lg transition-all',
        isOnline
          ? syncPending
            ? 'bg-yellow-500 text-white'
            : 'bg-green-500 text-white'
          : 'bg-red-500 text-white',
        className
      )}
    >
      {isOnline ? (
        syncPending ? (
          <>
            <RefreshCw className='h-4 w-4 animate-spin' />
            <span className='text-sm font-medium'>同期中...</span>
          </>
        ) : (
          <>
            <Wifi className='h-4 w-4' />
            <span className='text-sm font-medium'>オンライン</span>
          </>
        )
      ) : (
        <>
          <WifiOff className='h-4 w-4' />
          <span className='text-sm font-medium'>オフライン</span>
        </>
      )}

      {showDetails && (
        <div className='ml-2 text-xs opacity-90'>
          {!isOnline && <div>データは自動的に保存されます</div>}
          {syncPending && <div>オンライン復帰時に同期されます</div>}
          {lastSyncTime && <div>最終同期: {lastSyncTime.toLocaleTimeString('ja-JP')}</div>}
        </div>
      )}
    </div>
  )
}

export function OfflineBanner() {
  const [isOnline, setIsOnline] = useState(navigator.onLine)
  const [showBanner, setShowBanner] = useState(false)

  useEffect(() => {
    const handleOnline = () => {
      setIsOnline(true)
      setShowBanner(true)
      setTimeout(() => setShowBanner(false), 3000)
    }

    const handleOffline = () => {
      setIsOnline(false)
      setShowBanner(true)
    }

    window.addEventListener('online', handleOnline)
    window.addEventListener('offline', handleOffline)

    // Initial check
    if (!navigator.onLine) {
      setShowBanner(true)
    }

    return () => {
      window.removeEventListener('online', handleOnline)
      window.removeEventListener('offline', handleOffline)
    }
  }, [])

  if (!showBanner) {
    return null
  }

  return (
    <div
      className={cn(
        'fixed left-0 right-0 top-0 z-[100] flex items-center justify-center gap-2 px-4 py-2 text-sm font-medium transition-all',
        isOnline ? 'bg-green-500 text-white' : 'bg-orange-500 text-white'
      )}
    >
      {isOnline ? (
        <>
          <Wifi className='h-4 w-4' />
          <span>インターネット接続が復旧しました</span>
        </>
      ) : (
        <>
          <CloudOff className='h-4 w-4' />
          <span>オフラインモードで動作中 - データは自動保存されます</span>
        </>
      )}
    </div>
  )
}

