    // Add zoom behavior with touch support
    const zoom = d3
      .zoom()
      .scaleExtent([0.1, 4])
      .on('zoom', (event) => {
        container.attr('transform', event.transform)
      })

    svg.call(zoom)

    // Enable touch gestures
    if (isMobile) {
      svg.on('touchstart', function (event) {
        event.preventDefault()
