            <Triangle className='h-4 w-4 text-amber-500' />
            <span>Outputs</span>
          </div>
          <div className='mt-2 border-t pt-2'>
            <p className='text-xs text-gray-600'>Scroll to zoom, drag to pan</p>
            <p className='text-xs text-gray-600'>Click nodes for details</p>
          </div>
        </div>
      </div>

      <svg
        ref={svgRef}
        width='100%'
        height='100%'
        onWheel={handleWheel}
        onMouseDown={handleMouseDown}
        style={{ cursor: 'grab' }}
      >
        <defs>
          <marker
            id='arrowhead'
            markerWidth='10'
            markerHeight='7'
            refX='9'
            refY='3.5'
            orient='auto'
          >
            <polygon points='0 0, 10 3.5, 0 7' fill='#6B7280' />
          </marker>
          <filter id='glow'>
            <feGaussianBlur stdDeviation='3' result='coloredBlur' />
            <feMerge>
              <feMergeNode in='coloredBlur' />
              <feMergeNode in='SourceGraphic' />
            </feMerge>
          </filter>
        </defs>

        <g transform={`translate(${pan.x}, ${pan.y}) scale(${zoom})`}>
          {/* Render connections */}
          {ittoData.connections.map((conn, idx) => {
            const isHighlighted =
              hoveredNode && (conn.from === hoveredNode || conn.to === hoveredNode)
            const fromNode = allNodes.find((n) => n.id === conn.from)
            const toNode = allNodes.find((n) => n.id === conn.to)

            if (!fromNode || !toNode) {
              return null
            }

            return (
              <g key={idx}>
                <line
                  x1={fromNode.position.x}
                  y1={fromNode.position.y}
                  x2={toNode.position.x}
                  y2={toNode.position.y}
                  stroke={isHighlighted ? '#3B82F6' : '#E5E7EB'}
                  strokeWidth={isHighlighted ? 3 : 2}
                  markerEnd='url(#arrowhead)'
                  opacity={hoveredNode && !isHighlighted ? 0.2 : 1}
                  style={{
                    transition: 'all 0.3s ease',
                    filter: isHighlighted ? 'url(#glow)' : 'none',
                  }}
                >
                  {isHighlighted && (
                    <animate
                      attributeName='stroke-dasharray'
                      values='0,5;5,5'
                      dur='0.5s'
                      repeatCount='indefinite'
                    />
                  )}
                </line>
              </g>
            )
          })}

          {/* Render nodes */}
          {allNodes.map((node) => {
            const isHighlighted = hoveredNode === node.id || connectedNodes.has(node.id)
            //             const NodeShape = getNodeShape(node) // TODO: Will be used in future
            const color = getNodeColor(node)

            return (
              <g
                key={node.id}
                transform={`translate(${node.position.x}, ${node.position.y})`}
                className='cursor-pointer'
                onClick={() => setSelectedNode(node)}
                onMouseEnter={() => setHoveredNode(node.id)}
                onMouseLeave={() => setHoveredNode(null)}
                opacity={hoveredNode && !isHighlighted && hoveredNode !== node.id ? 0.3 : 1}
                style={{ transition: 'all 0.3s ease' }}
              >
                <circle
                  r={isHighlighted ? 35 : 30}
                  fill='white'
                  stroke={color}
                  strokeWidth={isHighlighted ? 4 : 2}
                  filter={isHighlighted ? 'url(#glow)' : 'none'}
                />
                {node.type === 'input' && <Circle x={-12} y={-12} size={24} color={color} />}
                {node.type === 'tool' && <Square x={-12} y={-12} size={24} color={color} />}
                {node.type === 'output' && <Triangle x={-12} y={-12} size={24} color={color} />}
                {!node.type && <Circle x={-12} y={-12} size={24} color={color} fill={color} />}
                <text
                  y={45}
                  textAnchor='middle'
                  className='pointer-events-none text-xs font-medium'
                  fill='#374151'
                >
                  {node.name.length > 20 ? node.name.substring(0, 20) + '...' : node.name}
                </text>
              </g>
            )
          })}
        </g>
      </svg>

      {/* Node details modal */}
      {selectedNode && (
        <div className='absolute bottom-4 right-4 z-10 max-w-md rounded-lg bg-white p-6 shadow-xl'>
          <div className='mb-4 flex items-start justify-between'>
            <h3 className='text-lg font-bold'>{selectedNode.name}</h3>
            <button
              onClick={() => setSelectedNode(null)}
              className='text-gray-400 hover:text-gray-600'
            >
              ×
            </button>
          </div>

          <div className='space-y-2 text-sm'>
            {selectedNode.type && (
              <p>
                <span className='font-semibold'>Type:</span>{' '}
                {selectedNode.type.charAt(0).toUpperCase() + selectedNode.type.slice(1)}
              </p>
            )}
            {selectedNode.group && (
              <p>
                <span className='font-semibold'>Process Group:</span> {selectedNode.group}
              </p>
            )}
            {selectedNode.area && (
              <p>
                <span className='font-semibold'>Knowledge Area:</span> {selectedNode.area}
              </p>
            )}

            <div className='mt-4 border-t pt-4'>
              <p className='flex items-center text-xs text-gray-600'>
                <Info className='mr-1 h-4 w-4' />
                Click other nodes to explore relationships
              </p>
            </div>
          </div>
        </div>
      )}
    </div>
  )
}

export default ITTONetworkDiagram

import React, { useState, useCallback, useEffect } from 'react'
import PMBOKMatrix from '../pages/PMBOKMatrix'
import ITTOForceGraph from './ITTOForceGraph'
import { Maximize2, Minimize2, RotateCcw, Grip } from 'lucide-react'
import { throttle } from '../../utils/performance'

const IntegratedView = React.memo(() => {
  const [splitRatio, setSplitRatio] = useState(50)
  const [isDragging, setIsDragging] = useState(false)
  const [fullscreenView, setFullscreenView] = useState(null)
  const [windowWidth, setWindowWidth] = useState(window.innerWidth)

  // Update window width on resize
  useEffect(() => {
    const handleResize = () => setWindowWidth(window.innerWidth)
    window.addEventListener('resize', handleResize)
    return () => window.removeEventListener('resize', handleResize)
  }, [])

  const isMobile = windowWidth < 768

  const handleMouseDown = useCallback((e) => {
    e.preventDefault()
    setIsDragging(true)
  }, [])

  const handleMouseMove = useCallback(
    throttle((e) => {
      if (isDragging) {
        const container = e.currentTarget.closest('.split-container')
        if (!container) {
          return
        }
        const rect = container.getBoundingClientRect()
        const x = e.clientX - rect.left
        const newRatio = (x / rect.width) * 100
        setSplitRatio(Math.max(20, Math.min(80, newRatio)))
      }
    }, 16),
    [isDragging]
  )

  const handleMouseUp = useCallback(() => {
    setIsDragging(false)
  }, [])

  const resetSplit = useCallback(() => {
    setSplitRatio(50)
    setFullscreenView(null)
  }, [])

  const toggleFullscreen = useCallback((view) => {
    setFullscreenView((prev) => (prev === view ? null : view))
  }, [])

  // Handle mobile view switching
  const setMobileView = useCallback((view) => {
    setFullscreenView(view === 'matrix' ? null : 'network')
  }, [])

  useEffect(() => {
    if (isDragging) {
      const handleGlobalMouseMove = (e) => handleMouseMove(e)
      const handleGlobalMouseUp = () => handleMouseUp()

      document.addEventListener('mousemove', handleGlobalMouseMove)
      document.addEventListener('mouseup', handleGlobalMouseUp)

      return () => {
        document.removeEventListener('mousemove', handleGlobalMouseMove)
        document.removeEventListener('mouseup', handleGlobalMouseUp)
      }
    }
  }, [isDragging, handleMouseMove, handleMouseUp])

  // Set initial view for mobile
  useEffect(() => {
    if (isMobile && fullscreenView === null) {
      setFullscreenView(null) // Show matrix view by default on mobile
    }
  }, [isMobile, fullscreenView])

  return (
    <div className='flex h-screen flex-col'>
      {/* Header */}
      <div className='flex items-center justify-between border-b bg-white px-2 py-2 sm:px-4'>
        <h2 className='text-sm font-semibold sm:text-lg'>Integrated View</h2>
        <div className='flex gap-2'>
          {!isMobile && (
            <button
              onClick={resetSplit}
              className='flex items-center gap-1 rounded bg-gray-100 px-2 py-1 text-xs transition-colors hover:bg-gray-200 sm:px-3 sm:text-sm'
            >
              <RotateCcw className='h-3 w-3 sm:h-4 sm:w-4' />
              <span className='hidden sm:inline'>Reset Layout</span>
            </button>
          )}
        </div>
      </div>

      {/* Split View Container */}
      <div
        className='split-container relative flex flex-1'
        onMouseMove={handleMouseMove}
        style={{ cursor: isDragging ? 'col-resize' : 'default' }}
      >
        {/* Left Panel - Matrix View */}
        <div
          className={`${fullscreenView === 'network' ? 'hidden' : ''} custom-scrollbar relative overflow-auto bg-gray-50`}
          style={{
            width: isMobile ? '100%' : fullscreenView === 'matrix' ? '100%' : `${splitRatio}%`,
