      .enter()
      .append('text')
      .attr('class', 'knowledge-area-label')
      .attr('x', -10)
      .attr('y', (d, i) => i * cellHeight + cellHeight / 2)
      .attr('text-anchor', 'end')
      .attr('dominant-baseline', 'middle')
      .style('font-size', '13px')
      .style('fill', '#374151')
      .text((d) => d.name)
      .style('cursor', 'pointer')
      .on('click', (event, d) => {
        const term = glossaryService.getTermByName(d.name)
        if (term) {
          setSelectedGlossaryTerm(term)
        }
      })

    // ヒートマップセル
    const cells = g
      .selectAll('.heatmap-cell')
      .data(
        knowledgeAreas.flatMap((area, i) =>
          processGroups.map((group, j) => ({
            area: area.id,
            areaName: area.name,
            group,
            value: heatmapData[area.id][group],
            x: j * cellWidth,
            y: i * cellHeight,
          }))
        )
      )
      .enter()
      .append('g')
      .attr('class', 'heatmap-cell')

    // セルの背景
    cells
      .append('rect')
      .attr('x', (d) => d.x)
      .attr('y', (d) => d.y)
      .attr('width', cellWidth - 2)
      .attr('height', cellHeight - 2)
      .attr('rx', 4)
      .attr('fill', (d) => (d.value === 0 ? '#e5e7eb' : colorScale(d.value)))
      .attr('stroke', '#fff')
      .attr('stroke-width', 2)
      .style('cursor', (d) => (d.value > 0 ? 'pointer' : 'default'))
      .on('mouseenter', function (event, d) {
        if (d.value > 0) {
          d3.select(this)
            .transition()
            .duration(200)
            .attr('stroke', '#3b82f6')
            .attr('stroke-width', 3)
          setHoveredCell(d)
        }
      })
      .on('mouseleave', function (_event, _d) {
        d3.select(this).transition().duration(200).attr('stroke', '#fff').attr('stroke-width', 2)
        setHoveredCell(null)
      })

    // 値のテキスト
    cells
      .append('text')
      .attr('x', (d) => d.x + cellWidth / 2)
      .attr('y', (d) => d.y + cellHeight / 2)
      .attr('text-anchor', 'middle')
      .attr('dominant-baseline', 'middle')
      .style('font-size', '20px')
      .style('font-weight', 'bold')
      .style('fill', (d) => (d.value > 3 ? '#fff' : '#374151'))
      .style('pointer-events', 'none')
      .text((d) => (d.value > 0 ? d.value : ''))

    // 凡例
    const legendWidth = 200
    const legendHeight = 20
    const legendX = width - margin.right - legendWidth - 20
    const legendY = margin.top - 80

    const legendScale = d3.scaleLinear().domain([0, 5]).range([0, legendWidth])

    const legendAxis = d3.axisBottom(legendScale).ticks(6).tickFormat(d3.format('d'))

    // 凡例のグラデーション
    const gradient = svg
      .append('defs')
      .append('linearGradient')
      .attr('id', 'legend-gradient')
      .attr('x1', '0%')
      .attr('x2', '100%')
      .attr('y1', '0%')
      .attr('y2', '0%')

    for (let i = 0; i <= 10; i++) {
      gradient
        .append('stop')
        .attr('offset', `${i * 10}%`)
        .attr('stop-color', colorScale(i / 2))
    }

    const legend = svg.append('g').attr('transform', `translate(${legendX},${legendY})`)

    legend
      .append('rect')
      .attr('width', legendWidth)
      .attr('height', legendHeight)
      .style('fill', 'url(#legend-gradient)')

    legend.append('g').attr('transform', `translate(0,${legendHeight})`).call(legendAxis)

    legend
      .append('text')
      .attr('x', legendWidth / 2)
      .attr('y', -5)
      .attr('text-anchor', 'middle')
      .style('font-size', '12px')
      .style('fill', '#6b7280')
      .text('値の範囲')

    // 統計情報
    const stats = calculateStats()
    const statsG = svg.append('g').attr('transform', `translate(${margin.left},${height - 40})`)

    statsG
      .selectAll('.stat')
      .data([
        { label: '最高値', value: stats.max, icon: TrendingUp },
        { label: '平均値', value: stats.avg.toFixed(1), icon: Activity },
        { label: '最低値', value: stats.min, icon: TrendingDown },
      ])
      .enter()
      .append('g')
      .attr('class', 'stat')
      .attr('transform', (d, i) => `translate(${i * 150},0)`)

    function calculateStats() {
      const values = Object.values(heatmapData).flatMap((area) =>
        Object.values(area).filter((v) => v > 0)
      )
      return {
        max: Math.max(...values),
        min: Math.min(...values),
        avg: values.reduce((a, b) => a + b, 0) / values.length,
      }
    }
  }, [dimensions, heatmapData, selectedMetric])

  return (
    <div className='flex h-screen w-full flex-col bg-gray-50'>
      {/* ヘッダー */}
      <div className='border-b bg-white p-4 shadow-sm'>
        <div className='mx-auto max-w-7xl'>
          <div className='flex items-center justify-between'>
            <div className='flex items-center gap-6'>
              {/* メトリクス選択 */}
              <div className='flex items-center gap-2'>
                <label className='text-sm font-medium text-gray-700'>表示指標:</label>
                <div className='flex gap-2'>
                  {metrics.map((metric) => (
                    <button
                      key={metric.id}
                      onClick={() => setSelectedMetric(metric.id)}
                      className={`rounded-lg px-3 py-1.5 text-sm font-medium transition-colors ${
                        selectedMetric === metric.id
                          ? 'bg-blue-500 text-white'
                          : 'bg-gray-100 text-gray-700 hover:bg-gray-200'
                      }`}
                    >
                      {metric.name}
                    </button>
                  ))}
                </div>
              </div>
            </div>

            <button
              className='flex items-center gap-2 text-sm text-gray-600 hover:text-gray-900'
              onClick={() => {
                const term = glossaryService.getTermByName('ヒートマップ')
                if (term) {
                  setSelectedGlossaryTerm(term)
                }
              }}
            >
              <Info className='h-4 w-4' />
              ヒートマップとは？
            </button>
          </div>
        </div>
      </div>

      {/* メインコンテンツ */}
      <div ref={containerRef} className='relative flex-1'>
        <svg ref={svgRef} className='h-full w-full' />

        {/* ツールチップ */}
        {hoveredCell && (
          <div
            className='pointer-events-none absolute z-10 rounded-lg bg-gray-900 p-3 text-white shadow-lg'
            style={{
              left: `${dimensions.width * 0.17 + hoveredCell.x + 50}px`,
              top: `${dimensions.height * 0.15 + hoveredCell.y - 10}px`,
              transform: 'translate(-50%, -100%)',
            }}
          >
            <div className='text-sm font-semibold'>{hoveredCell.areaName}</div>
            <div className='text-xs opacity-90'>{hoveredCell.group}</div>
            <div className='mt-1 text-lg font-bold'>{hoveredCell.value}</div>
          </div>
        )}
      </div>

      {/* 用語集ダイアログ */}
      {selectedGlossaryTerm && (
        <GlossaryDialog
          term={selectedGlossaryTerm}
          onClose={() => setSelectedGlossaryTerm(null)}
          onNavigateToGlossary={(termId) => {
            navigate('/glossary', { state: { selectedTermId: termId } })
          }}
