      { source: 'p5.3', target: 'p5.4', type: 'sequential' },
      { source: 'p4.1', target: 'p4.2', type: 'primary' },
      { source: 'p4.2', target: 'p4.4', type: 'feedback' },
      { source: 'p4.4', target: 'p4.5', type: 'trigger' },
      { source: 'p4.5', target: 'p4.2', type: 'update' },
