import React, { useEffect, useRef, useState, useMemo } from 'react'
import * as d3 from 'd3'
import { Download } from 'lucide-react'

const ProcessHeatmap = ({ data, progressData }) => {
  const svgRef = useRef(null)
  const containerRef = useRef(null)
  const [dimensions, setDimensions] = useState({ width: 1200, height: 800 })
  const [selectedMetric, setSelectedMetric] = useState('complexity')
  const [hoveredCell, setHoveredCell] = useState(null)
  const [showLegend, setShowLegend] = useState(true)

  // メトリクスの定義
  const metrics = {
    complexity: {
      name: '複雑度',
      description: 'ITTOの数に基づくプロセスの複雑さ',
      calculate: (process) => {
        if (!data) {
          return 0
        }
        const links = data.links.filter(
          (l) =>
            l.source === process.id ||
            l.source.id === process.id ||
            l.target === process.id ||
            l.target.id === process.id
        )
        return links.length
      },
    },
    progress: {
      name: '学習進捗',
      description: '各プロセスの学習完了度',
      calculate: (process) => {
        if (!progressData) {
          return 0
        }
        const progress = progressData[process.id]
        return progress ? progress.understandingLevel : 0
      },
    },
    connectivity: {
      name: '接続性',
      description: '他のプロセスとの関連度',
      calculate: (process) => {
        if (!data) {
          return 0
        }
        const connectedProcesses = new Set()
        data.links.forEach((link) => {
          if (link.source === process.id || link.source.id === process.id) {
            const target = data.nodes.find((n) => n.id === (link.target.id || link.target))
            if (target && target.type === 'process') {
              connectedProcesses.add(target.id)
            }
          }
          if (link.target === process.id || link.target.id === process.id) {
            const source = data.nodes.find((n) => n.id === (link.source.id || link.source))
            if (source && source.type === 'process') {
              connectedProcesses.add(source.id)
            }
          }
        })
        return connectedProcesses.size
      },
    },
    importance: {
      name: '重要度',
      description: 'PMP試験での出題頻度（推定）',
      calculate: (process) => {
        // 重要なプロセスのマッピング（仮の値）
        const importanceMap = {
          プロジェクト憲章の作成: 10,
          プロジェクトマネジメント計画書の作成: 10,
          'プロジェクト作業の指揮・マネジメント': 9,
          'プロジェクト作業の監視・コントロール': 9,
          統合変更管理: 10,
          スコープの定義: 8,
          WBSの作成: 9,
          スケジュールの作成: 9,
          コストの見積り: 8,
          リスクの特定: 9,
          'リスク分析（定性的）': 8,
          ステークホルダーの特定: 9,
          コミュニケーションの管理: 8,
        }
        return importanceMap[process.name] || 5
      },
    },
  }

  // レスポンシブ対応
  useEffect(() => {
    const updateDimensions = () => {
      if (containerRef.current) {
        const { width, height } = containerRef.current.getBoundingClientRect()
        setDimensions({
          width: width || 1200,
          height: height || 800,
        })
      }
    }

    updateDimensions()
    window.addEventListener('resize', updateDimensions)
    return () => window.removeEventListener('resize', updateDimensions)
  }, [])

  // ヒートマップデータの準備
  const heatmapData = useMemo(() => {
    if (!data) {
      return null
    }

    const processes = data.nodes.filter((n) => n.type === 'process')
    const knowledgeAreas = [
      '統合',
      'スコープ',
      'スケジュール',
      'コスト',
      '品質',
      '資源',
      'コミュニケーション',
      'リスク',
      '調達',
      'ステークホルダー',
    ]
    const processGroups = ['立ち上げ', '計画', '実行', '監視・コントロール', '終結']

    // マトリックスデータの作成
    const matrix = []
    knowledgeAreas.forEach((area, areaIndex) => {
      processGroups.forEach((group, groupIndex) => {
        const process = processes.find((p) => p.area === area && p.group === group)
        if (process) {
          const value = metrics[selectedMetric].calculate(process)
          matrix.push({
            area,
            group,
            areaIndex,
            groupIndex,
            process,
            value,
          })
        }
      })
    })

    return {
      matrix,
      knowledgeAreas,
      processGroups,
      maxValue: Math.max(...matrix.map((d) => d.value)),
    }
  }, [data, progressData, selectedMetric])

  // ヒートマップの描画
  useEffect(() => {
    if (!heatmapData || !svgRef.current) {
      return
    }

    const margin = { top: 120, right: 200, bottom: 60, left: 200 }
    const width = dimensions.width - margin.left - margin.right
    const height = dimensions.height - margin.top - margin.bottom

    // SVGのクリア
    const svg = d3.select(svgRef.current)
    svg.selectAll('*').remove()

    // グループの作成
    const g = svg.append('g').attr('transform', `translate(${margin.left},${margin.top})`)

    // スケールの設定
    const xScale = d3.scaleBand().domain(heatmapData.processGroups).range([0, width]).padding(0.1)

    const yScale = d3.scaleBand().domain(heatmapData.knowledgeAreas).range([0, height]).padding(0.1)

    // カラースケール
    const colorScale = d3
      .scaleSequential()
      .domain([0, heatmapData.maxValue])
      .interpolator(d3.interpolateYlOrRd)

    // セルの描画
    const cells = g
      .selectAll('.cell')
      .data(heatmapData.matrix)
      .enter()
      .append('g')
      .attr('class', 'cell')

    cells
      .append('rect')
      .attr('x', (d) => xScale(d.group))
      .attr('y', (d) => yScale(d.area))
      .attr('width', xScale.bandwidth())
      .attr('height', yScale.bandwidth())
      .attr('fill', (d) => colorScale(d.value))
      .attr('stroke', '#fff')
      .attr('stroke-width', 2)
      .attr('rx', 4)
      .attr('ry', 4)
      .style('cursor', 'pointer')
      .on('mouseenter', (event, d) => {
        setHoveredCell(d)
        d3.select(event.target).attr('stroke', '#333').attr('stroke-width', 3)
      })
      .on('mouseleave', (event) => {
        setHoveredCell(null)
        d3.select(event.target).attr('stroke', '#fff').attr('stroke-width', 2)
      })

    // セル内のテキスト（値）
    cells
      .append('text')
      .attr('x', (d) => xScale(d.group) + xScale.bandwidth() / 2)
      .attr('y', (d) => yScale(d.area) + yScale.bandwidth() / 2)
      .attr('text-anchor', 'middle')
      .attr('dy', '.35em')
      .attr('font-size', '14px')
      .attr('font-weight', 'bold')
      .attr('fill', (d) => (d.value > heatmapData.maxValue * 0.6 ? '#fff' : '#333'))
      .text((d) => d.value.toFixed(0))
      .style('pointer-events', 'none')

    // X軸（プロセス群）
    g.append('g')
      .attr('transform', `translate(0,${-10})`)
      .selectAll('text')
      .data(heatmapData.processGroups)
      .enter()
      .append('text')
      .attr('x', (d) => xScale(d) + xScale.bandwidth() / 2)
      .attr('y', 0)
      .attr('text-anchor', 'middle')
      .attr('font-size', '14px')
      .attr('font-weight', 'bold')
      .text((d) => d)

    // Y軸（知識エリア）
    g.append('g')
      .attr('transform', `translate(${-10},0)`)
      .selectAll('text')
      .data(heatmapData.knowledgeAreas)
      .enter()
      .append('text')
      .attr('x', 0)
      .attr('y', (d) => yScale(d) + yScale.bandwidth() / 2)
      .attr('text-anchor', 'end')
      .attr('dy', '.35em')
      .attr('font-size', '14px')
      .attr('font-weight', 'bold')
      .text((d) => `${d}マネジメント`)

    // タイトル
    svg
      .append('text')
      .attr('x', dimensions.width / 2)
      .attr('y', 40)
      .attr('text-anchor', 'middle')
      .attr('font-size', '20px')
      .attr('font-weight', 'bold')
      .text(`PMBOKプロセス ${metrics[selectedMetric].name}ヒートマップ`)

    // 凡例
    if (showLegend) {
      const legendWidth = 300
      const legendHeight = 20

      const legendScale = d3.scaleLinear().domain([0, heatmapData.maxValue]).range([0, legendWidth])

      const legendAxis = d3.axisBottom(legendScale).ticks(5).tickFormat(d3.format('.0f'))

      const legend = svg
        .append('g')
        .attr(
          'transform',
          `translate(${dimensions.width - margin.right - legendWidth - 50},${margin.top - 60})`
        )

      // グラデーション定義
      const gradient = svg
        .append('defs')
        .append('linearGradient')
        .attr('id', 'legend-gradient')
        .attr('x1', '0%')
        .attr('y1', '0%')
        .attr('x2', '100%')
        .attr('y2', '0%')

      const numStops = 10
      for (let i = 0; i <= numStops; i++) {
        gradient
          .append('stop')
          .attr('offset', `${(i / numStops) * 100}%`)
          .attr('stop-color', colorScale((i / numStops) * heatmapData.maxValue))
      }

      legend
        .append('rect')
        .attr('width', legendWidth)
        .attr('height', legendHeight)
        .attr('fill', 'url(#legend-gradient)')
        .attr('stroke', '#ccc')

      legend.append('g').attr('transform', `translate(0,${legendHeight})`).call(legendAxis)

      legend
        .append('text')
        .attr('x', legendWidth / 2)
        .attr('y', -10)
        .attr('text-anchor', 'middle')
        .attr('font-size', '12px')
        .text(metrics[selectedMetric].name)
    }
  }, [heatmapData, dimensions, selectedMetric, showLegend])

  // SVGエクスポート
  const exportSVG = () => {
    const svgElement = svgRef.current
    const svgData = new XMLSerializer().serializeToString(svgElement)
    const blob = new Blob([svgData], { type: 'image/svg+xml' })
    const url = URL.createObjectURL(blob)
    const link = document.createElement('a')
    link.href = url
    link.download = 'pmbok-heatmap.svg'
    link.click()
    URL.revokeObjectURL(url)
  }

  return (
    <div ref={containerRef} className='relative h-full w-full bg-gray-50'>
      {/* コントロールパネル */}
      <div className='absolute right-4 top-4 max-w-xs space-y-4 rounded-lg bg-white p-4 shadow-lg'>
        <div>
          <label className='mb-2 block text-sm font-medium text-gray-700'>表示メトリクス</label>
          <select
            value={selectedMetric}
            onChange={(e) => setSelectedMetric(e.target.value)}
            className='w-full rounded-md border border-gray-300 px-3 py-2'
          >
            {Object.entries(metrics).map(([key, metric]) => (
              <option key={key} value={key}>
                {metric.name}
              </option>
            ))}
          </select>
          <p className='mt-1 text-xs text-gray-600'>{metrics[selectedMetric].description}</p>
        </div>

        <div className='flex items-center gap-2'>
          <input
            type='checkbox'
            id='showLegend'
            checked={showLegend}
            onChange={(e) => setShowLegend(e.target.checked)}
            className='rounded'
          />
          <label htmlFor='showLegend' className='text-sm text-gray-700'>
            凡例を表示
          </label>
        </div>

        <button
          onClick={exportSVG}
          className='flex w-full items-center justify-center gap-2 rounded-md bg-green-600 px-3 py-2 text-white hover:bg-green-700'
        >
          <Download className='h-4 w-4' />
          SVGエクスポート
        </button>
      </div>

      {/* ホバー情報 */}
      {hoveredCell && (
        <div className='absolute bottom-4 left-4 max-w-sm rounded-lg bg-white p-4 shadow-lg'>
          <h3 className='font-semibold text-gray-900'>{hoveredCell.process.name}</h3>
          <p className='text-sm text-gray-600'>知識エリア: {hoveredCell.area}マネジメント</p>
          <p className='text-sm text-gray-600'>プロセス群: {hoveredCell.group}</p>
          <div className='mt-2 border-t pt-2'>
            <p className='text-sm font-semibold'>
              {metrics[selectedMetric].name}: {hoveredCell.value.toFixed(1)}
            </p>
            {selectedMetric === 'progress' && (
              <p className='text-sm text-gray-600'>
                理解度: {(hoveredCell.value * 10).toFixed(0)}%
              </p>
            )}
          </div>
        </div>
      )}

      {/* SVGキャンバス */}
      <svg
        ref={svgRef}
        width={dimensions.width}
        height={dimensions.height}
        className='h-full w-full'
      />
    </div>
  )
}

export default React.memo(ProcessHeatmap)

import React, { useEffect, useRef, useState, useMemo } from 'react'
import * as d3 from 'd3'
import {
  sankey,
  sankeyLinkHorizontal,
  sankeyLeft,
  sankeyRight,
  sankeyCenter,
  sankeyJustify,
} from 'd3-sankey'
import { Download, AlignLeft, AlignRight, AlignCenter, AlignJustify } from 'lucide-react'

const SankeyDiagram = ({ data }) => {
  const svgRef = useRef(null)
  const containerRef = useRef(null)
  const [selectedTheme, setSelectedTheme] = useState('default')
  const [selectedAlignment, setSelectedAlignment] = useState('justify')
  const [nodeWidth, setNodeWidth] = useState(15)
  const [nodePadding, setNodePadding] = useState(10)
  const [dimensions, setDimensions] = useState({ width: 1200, height: 800 })
  const [hoveredNode, setHoveredNode] = useState(null)
  const [hoveredLink, setHoveredLink] = useState(null)

  // カラーテーマ
  const themes = {
    default: {
      name: 'デフォルト',
      processGroup: {
        立ち上げ: '#8B5CF6',
        計画: '#3B82F6',
        実行: '#10B981',
        '監視・コントロール': '#F59E0B',
        終結: '#EF4444',
      },
      link: '#e0e0e0',
      linkHover: '#999',
      text: '#333',
      background: '#f9fafb',
    },
    ocean: {
      name: 'オーシャン',
      processGroup: {
        立ち上げ: '#0891b2',
        計画: '#0e7490',
        実行: '#155e75',
        '監視・コントロール': '#164e63',
        終結: '#134e4a',
      },
      link: '#cbd5e1',
      linkHover: '#64748b',
      text: '#1e293b',
      background: '#f0f9ff',
    },
    sunset: {
      name: 'サンセット',
      processGroup: {
        立ち上げ: '#f97316',
        計画: '#ea580c',
        実行: '#dc2626',
        '監視・コントロール': '#b91c1c',
        終結: '#991b1b',
      },
      link: '#fed7aa',
      linkHover: '#fb923c',
      text: '#451a03',
      background: '#fff7ed',
    },
  }

  // アラインメントオプション
  const alignments = {
    left: { name: '左寄せ', icon: AlignLeft, func: sankeyLeft },
    right: { name: '右寄せ', icon: AlignRight, func: sankeyRight },
    center: { name: '中央', icon: AlignCenter, func: sankeyCenter },
    justify: { name: '均等', icon: AlignJustify, func: sankeyJustify },
  }

  // レスポンシブ対応
  useEffect(() => {
    const updateDimensions = () => {
      if (containerRef.current) {
        const { width, height } = containerRef.current.getBoundingClientRect()
        setDimensions({
          width: width || 1200,
          height: height || 800,
        })
      }
    }

    updateDimensions()
    window.addEventListener('resize', updateDimensions)
    return () => window.removeEventListener('resize', updateDimensions)
  }, [])

  // サンキーデータの準備
  const sankeyData = useMemo(() => {
    if (!data) {
      return null
    }

    // ノードの作成（プロセス群とプロセス）
    const nodes = []
    const nodeMap = new Map()
    let nodeIndex = 0

    // プロセス群ノード
    const processGroups = ['立ち上げ', '計画', '実行', '監視・コントロール', '終結']
    processGroups.forEach((group) => {
      const node = { id: `pg_${group}`, name: group, type: 'processGroup', index: nodeIndex++ }
      nodes.push(node)
      nodeMap.set(node.id, node)
    })

    // プロセスノード（知識エリア別にグループ化）
    const processNodes = data.nodes.filter((n) => n.type === 'process')
    const knowledgeAreas = [...new Set(processNodes.map((p) => p.area))]

    knowledgeAreas.forEach((area) => {
      const areaProcesses = processNodes.filter((p) => p.area === area)
      areaProcesses.forEach((process) => {
        const node = {
          id: process.id,
          name: process.name,
          type: 'process',
          area: process.area,
          group: process.group,
          index: nodeIndex++,
        }
        nodes.push(node)
        nodeMap.set(node.id, node)
      })
    })

    // アウトプットノード（主要なもののみ）
    const majorOutputs = [
      'プロジェクト憲章',
      'プロジェクトマネジメント計画書',
      '成果物',
      '作業パフォーマンス・データ',
      '作業パフォーマンス報告書',
      '変更要求',
      '最終報告書',
    ]

    majorOutputs.forEach((outputName) => {
      const outputNode = data.nodes.find((n) => n.type === 'output' && n.name === outputName)
      if (outputNode) {
        const node = {
          id: outputNode.id,
          name: outputNode.name,
          type: 'output',
          index: nodeIndex++,
        }
        nodes.push(node)
        nodeMap.set(node.id, node)
      }
    })

    // リンクの作成
    const links = []

    // プロセス群からプロセスへのリンク
    processNodes.forEach((process) => {
      const sourceId = `pg_${process.group}`
      if (nodeMap.has(sourceId) && nodeMap.has(process.id)) {
        links.push({
          source: nodeMap.get(sourceId).index,
          target: nodeMap.get(process.id).index,
          value: 1,
          type: 'group-to-process',
        })
      }
    })

    // プロセスからアウトプットへのリンク
    data.links.forEach((link) => {
      if (link.type === 'output') {
        const sourceNode = nodeMap.get(link.source.id || link.source)
        const targetNode = nodeMap.get(link.target.id || link.target)
        if (sourceNode && targetNode && targetNode.type === 'output') {
          links.push({
            source: sourceNode.index,
            target: targetNode.index,
            value: 1,
            type: 'process-to-output',
            originalLink: link,
          })
        }
      }
    })

    return { nodes, links }
  }, [data])

  // サンキーダイアグラムの描画
  useEffect(() => {
    if (!sankeyData || !svgRef.current) {
      return
    }

    const theme = themes[selectedTheme]
    const margin = { top: 40, right: 150, bottom: 40, left: 150 }
    const width = dimensions.width - margin.left - margin.right
    const height = dimensions.height - margin.top - margin.bottom

    // SVGのクリア
    const svg = d3.select(svgRef.current)
    svg.selectAll('*').remove()

    // 背景色設定
    svg.style('background-color', theme.background)

    // グループの作成
    const g = svg.append('g').attr('transform', `translate(${margin.left},${margin.top})`)

    // サンキージェネレータの設定
    const sankeyGenerator = sankey()
      .nodeId((d) => d.index)
      .nodeAlign(alignments[selectedAlignment].func)
      .nodeWidth(nodeWidth)
      .nodePadding(nodePadding)
      .extent([
        [0, 0],
        [width, height],
      ])

    // データの処理
    const graph = sankeyGenerator({
      nodes: sankeyData.nodes.map((d) => ({ ...d })),
      links: sankeyData.links.map((d) => ({ ...d })),
    })

    // リンクの描画
    const link = g
      .append('g')
      .attr('fill', 'none')
      .selectAll('g')
      .data(graph.links)
      .join('g')
      .style('mix-blend-mode', 'multiply')

    link
      .append('path')
      .attr('d', sankeyLinkHorizontal())
      .attr('stroke', (d) => {
        if (d.type === 'group-to-process') {
          const targetNode = graph.nodes[d.target]
          return theme.processGroup[targetNode.group] || theme.link
        }
        return theme.link
      })
      .attr('stroke-width', (d) => Math.max(1, d.width))
      .attr('opacity', 0.5)
      .on('mouseenter', function (event, d) {
        setHoveredLink(d)
        d3.select(this).attr('stroke', theme.linkHover).attr('opacity', 0.8)
      })
      .on('mouseleave', function (event, d) {
        setHoveredLink(null)
        d3.select(this)
          .attr(
            'stroke',
            d.type === 'group-to-process'
              ? theme.processGroup[graph.nodes[d.target].group] || theme.link
              : theme.link
          )
          .attr('opacity', 0.5)
      })

    // ノードの描画
    const node = g.append('g').selectAll('g').data(graph.nodes).join('g')

    node
      .append('rect')
      .attr('x', (d) => d.x0)
      .attr('y', (d) => d.y0)
      .attr('height', (d) => d.y1 - d.y0)
      .attr('width', (d) => d.x1 - d.x0)
      .attr('fill', (d) => {
        if (d.type === 'processGroup') {
          return theme.processGroup[d.name]
        } else if (d.type === 'process') {
          return d3.color(theme.processGroup[d.group]).brighter(0.5)
        } else {
          return '#94a3b8'
        }
      })
      .attr('stroke', (d) =>
        d3
          .color(
            d.type === 'processGroup'
              ? theme.processGroup[d.name]
              : d.type === 'process'
                ? theme.processGroup[d.group]
                : '#64748b'
          )
          .darker(0.5)
      )
      .attr('stroke-width', 1)
      .on('mouseenter', function (event, d) {
        setHoveredNode(d)
        d3.select(this).attr('opacity', 0.8)
      })
      .on('mouseleave', function () {
        setHoveredNode(null)
        d3.select(this).attr('opacity', 1)
      })

    // ノードラベルの描画
    node
      .append('text')
      .attr('x', (d) => (d.x0 < width / 2 ? d.x1 + 6 : d.x0 - 6))
      .attr('y', (d) => (d.y1 + d.y0) / 2)
      .attr('dy', '0.35em')
      .attr('text-anchor', (d) => (d.x0 < width / 2 ? 'start' : 'end'))
      .attr('font-size', (d) => (d.type === 'processGroup' ? '14px' : '12px'))
      .attr('font-weight', (d) => (d.type === 'processGroup' ? 'bold' : 'normal'))
      .attr('fill', theme.text)
      .text((d) => d.name)
      .append('tspan')
      .attr('fill', '#666')
      .attr('font-size', '10px')
      .attr('dy', '1.2em')
      .attr('x', (d) => (d.x0 < width / 2 ? d.x1 + 6 : d.x0 - 6))
      .text((d) => (d.type === 'process' ? `(${d.area})` : ''))

    // タイトル
    svg
      .append('text')
      .attr('x', dimensions.width / 2)
      .attr('y', 20)
      .attr('text-anchor', 'middle')
      .attr('font-size', '18px')
      .attr('font-weight', 'bold')
      .attr('fill', theme.text)
      .text('PMBOKプロセスフロー サンキーダイアグラム')
  }, [sankeyData, dimensions, selectedTheme, selectedAlignment, nodeWidth, nodePadding])

  // SVGエクスポート
  const exportSVG = () => {
    const svgElement = svgRef.current
    const svgData = new XMLSerializer().serializeToString(svgElement)
    const blob = new Blob([svgData], { type: 'image/svg+xml' })
    const url = URL.createObjectURL(blob)
    const link = document.createElement('a')
    link.href = url
    link.download = 'pmbok-sankey-diagram.svg'
    link.click()
    URL.revokeObjectURL(url)
  }

  return (
    <div ref={containerRef} className='relative h-full w-full bg-gray-50'>
      {/* コントロールパネル */}
      <div className='absolute right-4 top-4 max-w-xs space-y-4 rounded-lg bg-white p-4 shadow-lg'>
        <div>
          <label className='mb-2 block text-sm font-medium text-gray-700'>カラーテーマ</label>
          <select
            value={selectedTheme}
            onChange={(e) => setSelectedTheme(e.target.value)}
            className='w-full rounded-md border border-gray-300 px-3 py-2'
          >
            {Object.entries(themes).map(([key, theme]) => (
              <option key={key} value={key}>
                {theme.name}
              </option>
            ))}
          </select>
        </div>

        <div>
          <label className='mb-2 block text-sm font-medium text-gray-700'>ノード配置</label>
          <div className='grid grid-cols-2 gap-2'>
            {Object.entries(alignments).map(([key, alignment]) => {
              const Icon = alignment.icon
              return (
                <button
                  key={key}
                  onClick={() => setSelectedAlignment(key)}
                  className={`flex items-center justify-center gap-2 rounded-md px-3 py-2 ${
                    selectedAlignment === key
                      ? 'bg-blue-600 text-white'
                      : 'bg-gray-100 text-gray-700 hover:bg-gray-200'
                  }`}
                >
                  <Icon className='h-4 w-4' />
                  <span className='text-sm'>{alignment.name}</span>
                </button>
              )
            })}
          </div>
        </div>

        <div>
          <label className='mb-2 block text-sm font-medium text-gray-700'>
            ノード幅: {nodeWidth}px
          </label>
          <input
            type='range'
            min='5'
            max='30'
            value={nodeWidth}
            onChange={(e) => setNodeWidth(Number(e.target.value))}
            className='w-full'
          />
        </div>

        <div>
          <label className='mb-2 block text-sm font-medium text-gray-700'>
            ノード間隔: {nodePadding}px
          </label>
          <input
            type='range'
            min='5'
            max='30'
            value={nodePadding}
            onChange={(e) => setNodePadding(Number(e.target.value))}
            className='w-full'
          />
        </div>

        <button
          onClick={exportSVG}
          className='flex w-full items-center justify-center gap-2 rounded-md bg-green-600 px-3 py-2 text-white hover:bg-green-700'
        >
          <Download className='h-4 w-4' />
          SVGエクスポート
        </button>
      </div>

      {/* ホバー情報 */}
      {(hoveredNode || hoveredLink) && (
        <div className='absolute bottom-4 left-4 max-w-sm rounded-lg bg-white p-4 shadow-lg'>
          {hoveredNode && (
            <>
              <h3 className='font-semibold text-gray-900'>{hoveredNode.name}</h3>
              {hoveredNode.type === 'process' && (
                <>
                  <p className='text-sm text-gray-600'>プロセス群: {hoveredNode.group}</p>
                  <p className='text-sm text-gray-600'>知識エリア: {hoveredNode.area}</p>
                </>
              )}
              <p className='text-sm text-gray-600'>
                タイプ:{' '}
                {hoveredNode.type === 'processGroup'
                  ? 'プロセス群'
                  : hoveredNode.type === 'process'
                    ? 'プロセス'
                    : 'アウトプット'}
              </p>
            </>
          )}
          {hoveredLink && (
            <>
              <p className='text-sm text-gray-600'>
                接続:{' '}
                {hoveredLink.type === 'group-to-process'
                  ? 'プロセス群 → プロセス'
                  : 'プロセス → アウトプット'}
              </p>
            </>
          )}
        </div>
      )}

      {/* SVGキャンバス */}
      <svg
        ref={svgRef}
        width={dimensions.width}
        height={dimensions.height}
        className='h-full w-full'
      />
    </div>
  )
}

export default React.memo(SankeyDiagram)

import React, {
  createContext,
  useContext,
  useState,
  useEffect,
  useCallback,
  ReactNode,
} from 'react'
import { authService, UserRoles } from '../services/authService'
import { supabase, authHelpers, sessionManager } from '../lib/supabase'
import { auditLogger } from '../services/auditService'
import { useNavigate } from 'react-router-dom'
import toast from 'react-hot-toast'
import { logger } from '../services/logger'

interface User {
  id: string
  email: string
  name?: string
  avatar?: string
  created_at: string
  updated_at: string
}

interface Session {
  access_token: string
  refresh_token: string
  user: User
  expires_at: number
}

interface AuthContextType {
  user: User | null
  session: Session | null
  role: string
  permissions: string[]
  loading: boolean
  authError: string | null
  isAuthenticated: boolean
  signIn: (email: string, password: string) => Promise<{ success: boolean; error?: string }>
  signUp: (
    email: string,
    password: string,
    userData?: Record<string, unknown>
  ) => Promise<{ success: boolean; error?: string }>
  signOut: () => Promise<void>
  resetPassword: (email: string) => Promise<{ success: boolean; error?: string }>
  updateProfile: (userData: Partial<User>) => Promise<{ success: boolean; error?: string }>
  hasRole: (requiredRole: string) => boolean
  hasPermission: (permission: string) => boolean
  refreshSession: () => Promise<void>
}

// Create Auth Context
const AuthContext = createContext<AuthContextType | null>(null)

interface AuthProviderProps {
  children: ReactNode
}

// Helper component that uses navigation
const AuthProviderWithNavigation: React.FC<AuthProviderProps> = ({ children }) => {
  const navigate = useNavigate()
  return <AuthProviderInternal navigate={navigate}>{children}</AuthProviderInternal>
}

// Internal Auth Provider Component
interface AuthProviderInternalProps extends AuthProviderProps {
  navigate?: ReturnType<typeof useNavigate>
}

const AuthProviderInternal: React.FC<AuthProviderInternalProps> = ({ children, navigate }) => {
  // Hooks must be called at the top level
  const [user, setUser] = useState<User | null>(null)
  const [session, setSession] = useState<Session | null>(null)
  const [role, setRole] = useState<string>(UserRoles.GUEST)
  const [permissions, setPermissions] = useState<string[]>([])
  const [loading, setLoading] = useState<boolean>(true)
  const [authError, setAuthError] = useState<string | null>(null)

  // Initialize auth state
  useEffect(() => {
    let authSubscription

    const initializeAuth = async () => {
      try {
        // Get current session
        const currentSession = await authHelpers.getCurrentSession()

        if (currentSession) {
          setSession(currentSession)

          // Get user details
          const currentUser = await authHelpers.getCurrentUser()
          setUser(currentUser)

          // Get user role
          if (currentUser) {
            const userRole = await authHelpers.getUserRole(currentUser.id)
            setRole(userRole)

            // Load permissions for role
            await loadPermissions(userRole)
          }
        }

        // Start session monitoring
        authSubscription = sessionManager.startSessionMonitoring((event, session) => {
          handleAuthStateChange(event, session)
        })

        // Setup auto-refresh
        sessionManager.setupAutoRefresh()
      } catch (error) {
        // Silently handle initialization errors in production
        if (process.env.NODE_ENV === 'development') {
          logger.error('Auth initialization error:', error)
        }
        setAuthError(error?.message || 'Authentication initialization failed')
      } finally {
        setLoading(false)
      }
    }

    initializeAuth()

    // Cleanup
    return () => {
      if (authSubscription) {
        sessionManager.stopSessionMonitoring(authSubscription)
      }
    }
  }, [])

  // Handle auth state changes
  const handleAuthStateChange = async (event, session) => {
    // Log auth state changes in development only
    if (process.env.NODE_ENV === 'development') {
      logger.debug('Auth state changed:', event)
    }

    switch (event) {
      case 'SIGNED_IN':
        setSession(session)
        if (session?.user) {
          setUser(session.user)
          const userRole = await authHelpers.getUserRole(session.user.id)
          setRole(userRole)
          await loadPermissions(userRole)
        }
        break

      case 'SIGNED_OUT':
        setUser(null)
        setSession(null)
        setRole(UserRoles.GUEST)
        setPermissions([])
        if (navigate) {
          navigate('/login')
        }
        break

      case 'TOKEN_REFRESHED':
        setSession(session)
        break

      case 'USER_UPDATED':
        if (session?.user) {
          setUser(session.user)
        }
        break

      default:
        break
    }
  }

  // Load permissions for role
  const loadPermissions = async (userRole) => {
    try {
      // Define permissions based on role
      const rolePermissions = {
        [UserRoles.ADMIN]: [
          'view_all_content',
          'edit_all_content',
          'delete_all_content',
          'manage_users',
          'view_audit_logs',
          'manage_settings',
          'export_data',
          'import_data',
        ],
        [UserRoles.INSTRUCTOR]: [
          'view_all_content',
          'edit_own_content',
          'create_content',
          'view_student_progress',
          'grade_exams',
          'manage_groups',
          'export_data',
        ],
        [UserRoles.STUDENT]: [
          'view_content',
          'take_exams',
          'view_own_progress',
          'join_groups',
          'create_notes',
          'export_own_data',
        ],
        [UserRoles.GUEST]: ['view_public_content'],
      }

      setPermissions(rolePermissions[userRole] || [])
    } catch (error) {
      if (process.env.NODE_ENV === 'development') {
        logger.error('Load permissions error:', error)
      }
    }
  }

  // Sign up
  const signUp = useCallback(
    async (email, password, profile) => {
      setLoading(true)
      setAuthError(null)

      try {
        const result = await authService.register(email, password, profile)

        if (result.user) {
          toast.success('Registration successful! Please check your email to verify your account.')
          navigate('/verify-email')
        }

        return result
      } catch (error) {
        setAuthError(error.message)
        toast.error(error.message || 'Registration failed')
        throw error
      } finally {
        setLoading(false)
      }
    },
    [navigate]
  )

  // Sign in
  const signIn = useCallback(
    async (email, password) => {
      setLoading(true)
      setAuthError(null)

      try {
        const result = await authService.signIn(email, password)

        if (result.user) {
          setUser(result.user)
          setSession(result.session)
          setRole(result.role)
          await loadPermissions(result.role)

          toast.success('Welcome back!')
          navigate('/')
        }

        return result
      } catch (error) {
        setAuthError(error.message)

        // Handle specific errors
        if (error.message.includes('Invalid login credentials')) {
          toast.error('Invalid email or password')
        } else if (error.message.includes('Email not confirmed')) {
          toast.error('Please verify your email before signing in')
        } else if (error.message === 'account_locked') {
          const remainingTime = authService.getLockoutRemainingTime(email)
          toast.error(`Account locked. Try again in ${Math.ceil(remainingTime / 60)} minutes`)
        } else {
          toast.error(error.message || 'Sign in failed')
        }

        throw error
      } finally {
        setLoading(false)
      }
    },
    [navigate]
  )

  // Sign in with OAuth
  const _signInWithOAuth = useCallback(async (provider) => {
    setLoading(true)
    setAuthError(null)

    try {
      await authService.signInWithOAuth(provider)
      // OAuth will redirect, so no need to handle success here
    } catch (error) {
      setAuthError(error.message)
      toast.error(`${provider} sign in failed`)
      throw error
    } finally {
      setLoading(false)
    }
  }, [])

  // Sign out
  const signOut = useCallback(async () => {
    setLoading(true)

    try {
      await authService.signOut()
      toast.success('Signed out successfully')
    } catch (error) {
      if (process.env.NODE_ENV === 'development') {
        logger.error('Sign out error:', error)
      }
      toast.error('Sign out failed')
    } finally {
      setLoading(false)
    }
  }, [])

  // Reset password
  const resetPassword = useCallback(async (email) => {
    setLoading(true)
    setAuthError(null)

    try {
      await authService.resetPassword(email)
      toast.success('Password reset email sent! Check your inbox.')
      return true
    } catch (error) {
      setAuthError(error.message)
      toast.error('Password reset failed')
      throw error
    } finally {
      setLoading(false)
    }
  }, [])

  // Update password
  const _updatePassword = useCallback(async (newPassword) => {
    setLoading(true)
    setAuthError(null)

    try {
      await authService.updatePassword(newPassword)
      toast.success('Password updated successfully')
      return true
    } catch (error) {
      setAuthError(error.message)
      toast.error(error.message || 'Password update failed')
      throw error
    } finally {
      setLoading(false)
    }
  }, [])

  // Check permission
  const hasPermission = useCallback(
    (permission) => {
      return permissions.includes(permission)
    },
    [permissions]
  )

  // Check role
  const hasRole = useCallback(
    (requiredRole) => {
      const roleHierarchy = {
        [UserRoles.ADMIN]: 4,
        [UserRoles.INSTRUCTOR]: 3,
        [UserRoles.STUDENT]: 2,
        [UserRoles.GUEST]: 1,
      }

      return roleHierarchy[role] >= roleHierarchy[requiredRole]
    },
    [role]
  )

  // Update user profile
  const updateProfile = useCallback(async (updates) => {
    setLoading(true)

    try {
      const { data, error } = await supabase.auth.updateUser({
        data: updates,
      })

      if (error) {
        throw error
      }

      setUser(data.user)
      toast.success('Profile updated successfully')

      await auditLogger.log({
        action: 'USER_UPDATED',
        userId: data.user.id,
        details: { updates },
      })

      return data.user
    } catch (error) {
      toast.error('Profile update failed')
      throw error
    } finally {
      setLoading(false)
    }
  }, [])

  // Context value
  const value: AuthContextType = {
    // State
    user,
    session,
    role,
    permissions,
    loading,
    authError,
    isAuthenticated: !!user,

    // Methods
    signUp,
    signIn,
    signOut,
    resetPassword,
    updateProfile,
    hasPermission,
    hasRole,
    refreshSession: async () => {
      try {
        const { data, error } = await supabase.auth.refreshSession()
        if (error) {
          throw error
        }
        if (data.session) {
          setSession(data.session)
        }
      } catch (error) {
        logger.error('Failed to refresh session:', error)
        setAuthError('Session refresh failed')
      }
    },
  }

  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>
}

// Export the AuthProvider that automatically handles navigation
export const AuthProvider: React.FC<AuthProviderProps> = ({ children }) => {
  // Try to use navigation if available (inside Router)
  try {
    return <AuthProviderWithNavigation>{children}</AuthProviderWithNavigation>
  } catch {
    // Fallback to provider without navigation (for tests or outside Router)
    return <AuthProviderInternal>{children}</AuthProviderInternal>
  }
}

// Custom hook to use auth context
export const useAuth = (): AuthContextType => {
  const context = useContext(AuthContext)

  if (!context) {
    throw new Error('useAuth must be used within an AuthProvider')
  }

  return context
}

// HOC for protected components
export const withAuth = (Component, requiredRole = null) => {
  const WrappedComponent = (props) => {
    const { isAuthenticated, role, loading, hasRole } = useAuth()
    const navigate = useNavigate()

    useEffect(() => {
      if (!loading && !isAuthenticated) {
        navigate('/login')
      } else if (!loading && requiredRole && hasRole && !hasRole(requiredRole)) {
        navigate('/unauthorized')
      }
    }, [isAuthenticated, role, loading, navigate, hasRole])

    if (loading) {
      return (
        <div className='flex min-h-screen items-center justify-center'>
          <div className='h-12 w-12 animate-spin rounded-full border-b-2 border-blue-600'></div>
        </div>
      )
    }

    if (!isAuthenticated) {
      return null
    }

    if (requiredRole && !hasRole(requiredRole)) {
      return null
    }

    return <Component {...props} />
  }

  WrappedComponent.displayName = `withAuth(${Component.displayName || Component.name || 'Component'})`

  return WrappedComponent
}

export default AuthContext

/**
 * Context Manager React Context
 * Provides context management services throughout the React application
 */

import React, { createContext, useContext, useEffect, useState, useMemo, ReactNode } from 'react'
import contextManager from '../services/contextManager.js'
import contextMonitor from '../services/contextMonitor.js'
import performanceOptimizer from '../services/performanceOptimizer.js'
import type {
  ContextManagerAPI,
  ContextStats,
  MonitoringData,
  PerformanceMetrics,
  StoreOptions,
  ContextMonitoringReturn,
  ContextStorageReturn,
  PerformanceOptimizerReturn,
} from '../types/context'

const ContextManagerContext = createContext<ContextManagerAPI | null>(null)

interface ContextManagerProviderProps {
  children: ReactNode
}

export const ContextManagerProvider: React.FC<ContextManagerProviderProps> = ({ children }) => {
  const [contextStats, setContextStats] = useState<ContextStats>({
    totalEntries: 0,
    totalSizeKB: 0,
    cacheHitRate: 0.85,
    averageAccessCount: 0,
    compressionRatio: 0,
  })

  const [monitoringData, setMonitoringData] = useState<MonitoringData>({
    status: 'healthy',
    policy: 'normal',
    metrics: {},
    lastCleanup: Date.now(),
  })

  const [performanceMetrics, setPerformanceMetrics] = useState<PerformanceMetrics>({
    memory: { usedMB: 0, totalMB: 0, limitMB: 0 },
    cache: { lazyLoadCacheSize: 0 },
  })

  // Update stats periodically
  useEffect(() => {
    const updateStats = () => {
      setContextStats(contextManager.getStats())
      setMonitoringData(contextMonitor.getDashboardData())
      setPerformanceMetrics(performanceOptimizer.getPerformanceMetrics())
    }

    // Initial update
    updateStats()

    // Update every 30 seconds
    const interval = setInterval(updateStats, 30000)

    return () => clearInterval(interval)
  }, [])

  // Context management API
  const contextAPI = useMemo<ContextManagerAPI>(
    () => ({
      // Storage operations
      store: (key: string, data: any, options?: StoreOptions) => {
        const start = performance.now()
        const result = contextManager.store(key, data, options)
        const duration = performance.now() - start

        contextMonitor.recordRetrievalTime(duration)
        return result
      },

      retrieve: (key: string) => {
        const start = performance.now()
        try {
          const result = contextManager.retrieve(key)
          const duration = performance.now() - start

          contextMonitor.recordRetrievalTime(duration)
          return result
        } catch (error) {
          contextMonitor.recordError()
          throw error
        }
      },

      // Cleanup operations
      cleanup: async () => {
        return await contextManager.cleanup()
      },

      archive: async (maxAge: number) => {
        return await contextManager.archiveOldData(maxAge)
      },

      clear: () => {
        contextManager.clear()
      },

      // Performance operations
      optimizeComponent: (Component: React.ComponentType, options?: any) => {
        return performanceOptimizer.optimizeComponent(Component, options)
      },

      lazyLoad: async (componentKey: string, loader: () => Promise<any>) => {
        return await performanceOptimizer.lazyLoadComponent(componentKey, loader)
      },

      observeForLazyLoading: (element: Element, loadHandler: () => void) => {
        return performanceOptimizer.observeForLazyLoading(element, loadHandler)
      },

      debounce: <T extends (...args: any[]) => any>(func: T, wait: number) => {
        return performanceOptimizer.debounce(func, wait)
      },

      throttle: <T extends (...args: any[]) => any>(func: T, limit: number) => {
        return performanceOptimizer.throttle(func, limit)
      },

      // Monitoring operations
      setRotationPolicy: (policy: 'normal' | 'aggressive' | 'conservative') => {
        contextMonitor.setRotationPolicy(policy)
      },

      getDiagnostics: () => {
        return contextMonitor.performDiagnostics()
      },

      // Statistics
      getStats: () => contextStats,
      getMonitoringData: () => monitoringData,
      getPerformanceMetrics: () => performanceMetrics,
    }),
    [contextStats, monitoringData, performanceMetrics]
  )

  return (
    <ContextManagerContext.Provider value={contextAPI}>{children}</ContextManagerContext.Provider>
  )
}

// Custom hook to use context manager
export const useContextManager = (): ContextManagerAPI => {
  const context = useContext(ContextManagerContext)

  if (!context) {
    throw new Error('useContextManager must be used within a ContextManagerProvider')
  }

  return context
}

// Hook for performance optimization
export const usePerformanceOptimizer = (): PerformanceOptimizerReturn => {
  const { optimizeComponent, lazyLoad, observeForLazyLoading, debounce, throttle } =
    useContextManager()

  return {
    optimizeComponent,
    lazyLoad,
    observeForLazyLoading,
    debounce,
    throttle,
  }
}

// Hook for context storage
export const useContextStorage = (): ContextStorageReturn => {
  const { store, retrieve, cleanup, archive, clear } = useContextManager()

  return {
    store,
    retrieve,
    cleanup,
    archive,
    clear,
  }
}

// Hook for monitoring
export const useContextMonitoring = (): ContextMonitoringReturn => {
  const { setRotationPolicy, getDiagnostics, getStats, getMonitoringData, getPerformanceMetrics } =
    useContextManager()

  const [isMonitoring, setIsMonitoring] = useState(true)

  const toggleMonitoring = () => {
    setIsMonitoring(!isMonitoring)
  }

  return {
    setRotationPolicy,
    getDiagnostics,
    getStats,
    getMonitoringData,
    getPerformanceMetrics,
    isMonitoring,
    toggleMonitoring,
  }
}

// HOC for automatic performance optimization
export const withPerformanceOptimization = <P extends object>(
  Component: React.ComponentType<P>,
  options = {}
) => {
  const OptimizedComponent = React.memo(Component)

  OptimizedComponent.displayName = `Optimized(${Component.displayName || Component.name})`

  const EnhancedComponent = (props) => {
    usePerformanceOptimizer() // Call hook without destructuring

    // Apply additional optimizations if needed
    useEffect(() => {
      if (options.preload) {
        // Preload related components
      }
    }, [])

    return <OptimizedComponent {...props} />
  }

  EnhancedComponent.displayName = `withPerformanceOptimization(${Component.displayName || Component.name || 'Component'})`

  return EnhancedComponent
}

export default ContextManagerContext

/**
 * @file OfflineContext.tsx
 * @description オフライン機能のコンテキストプロバイダー
 * @author Developer 9 (frontend-developer) - React/状態管理
