import { useState, useEffect, useCallback, useRef } from 'react'

interface OfflineState {
  isOnline: boolean
  isServiceWorkerReady: boolean
  isSyncing: boolean
  syncQueue: number
  lastSyncTime: Date | null
  offlineDataSize: number
}

interface UseOfflineOptions {
  enableAutoSync?: boolean
  syncInterval?: number
  onStatusChange?: (isOnline: boolean) => void
  onSyncComplete?: () => void
}

export function useOffline(options: UseOfflineOptions = {}) {
  const {
    enableAutoSync = true,
    syncInterval = 60000, // 1 minute
    onStatusChange,
    onSyncComplete,
  } = options

  const [state, setState] = useState<OfflineState>({
    isOnline: navigator.onLine,
    isServiceWorkerReady: false,
    isSyncing: false,
    syncQueue: 0,
    lastSyncTime: null,
    offlineDataSize: 0,
  })

  const syncTimeoutRef = useRef<NodeJS.Timeout>()
  const dbRef = useRef<IDBDatabase | null>(null)

  // Initialize IndexedDB connection
  const initDatabase = useCallback(async () => {
    try {
      const request = indexedDB.open('PMPLearningOfflineDB', 1)

      request.onsuccess = () => {
        dbRef.current = request.result
        checkOfflineDataSize()
      }

      request.onupgradeneeded = (event: IDBVersionChangeEvent) => {
        const db = (event.target as IDBOpenDBRequest).result

        if (!db.objectStoreNames.contains('syncQueue')) {
          db.createObjectStore('syncQueue', { keyPath: 'id', autoIncrement: true })
        }
        if (!db.objectStoreNames.contains('offlineData')) {
          db.createObjectStore('offlineData', { keyPath: 'key' })
        }
      }
    } catch (error) {
      console.error('Failed to initialize IndexedDB:', error)
    }
  }, [])

  // Check offline data size
  const checkOfflineDataSize = useCallback(async () => {
    if (!dbRef.current) {
      return
    }

    try {
      // Estimate storage usage
      if ('storage' in navigator && 'estimate' in navigator.storage) {
        const estimate = await navigator.storage.estimate()
        const usageInMB = ((estimate.usage || 0) / (1024 * 1024)).toFixed(2)

        setState((prev) => ({
          ...prev,
          offlineDataSize: parseFloat(usageInMB),
        }))
      }

      // Check sync queue size
      const tx = dbRef.current.transaction(['syncQueue'], 'readonly')
      const store = tx.objectStore('syncQueue')
      const countRequest = store.count()

      countRequest.onsuccess = () => {
        setState((prev) => ({
          ...prev,
          syncQueue: countRequest.result,
        }))
      }
    } catch (error) {
      console.error('Failed to check offline data size:', error)
    }
  }, [])

  // Register service worker
  const registerServiceWorker = useCallback(async () => {
    if ('serviceWorker' in navigator) {
      try {
        const registration = await navigator.serviceWorker.register('/PMPLearningManagement/sw.js')

        setState((prev) => ({
          ...prev,
          isServiceWorkerReady: true,
        }))

        // Check for updates
        registration.addEventListener('updatefound', () => {
          const newWorker = registration.installing
          if (newWorker) {
            newWorker.addEventListener('statechange', () => {
              if (newWorker.state === 'activated') {
                console.log('Service Worker updated')
                // Optionally reload the page or notify the user
              }
            })
          }
        })

        return registration
      } catch (error) {
        console.error('Service Worker registration failed:', error)
      }
    }
  }, [])

  // Trigger background sync
  const triggerSync = useCallback(async (tag: string = 'offline-queue') => {
    if (!('serviceWorker' in navigator) || !('sync' in ServiceWorkerRegistration.prototype)) {
      console.warn('Background sync not supported')
      return false
    }

    try {
      const registration = await navigator.serviceWorker.ready
      // @ts-ignore - sync is not in TypeScript types yet
      await registration.sync.register(tag)

      setState((prev) => ({
        ...prev,
        isSyncing: true,
      }))

      return true
    } catch (error) {
      console.error('Failed to trigger sync:', error)
      return false
    }
  }, [])

  // Add item to offline queue
  const addToOfflineQueue = useCallback(
    async (data: {
      url: string
      method?: string
      headers?: Record<string, string>
      body?: any
    }) => {
      if (!dbRef.current) {
        console.error('Database not initialized')
        return false
      }

      try {
        const tx = dbRef.current.transaction(['syncQueue'], 'readwrite')
        const store = tx.objectStore('syncQueue')

        const request = store.add({
          ...data,
          timestamp: Date.now(),
          retries: 0,
        })

        return new Promise<boolean>((resolve) => {
          request.onsuccess = () => {
            checkOfflineDataSize()
            resolve(true)
          }
          request.onerror = () => {
            console.error('Failed to add to offline queue')
            resolve(false)
          }
        })
      } catch (error) {
        console.error('Failed to add to offline queue:', error)
        return false
      }
    },
    [checkOfflineDataSize]
  )

  // Clear offline data
  const clearOfflineData = useCallback(async () => {
    if (!dbRef.current) {
      return false
    }

    try {
      const stores = ['syncQueue', 'offlineData']

      for (const storeName of stores) {
        const tx = dbRef.current.transaction([storeName], 'readwrite')
        const store = tx.objectStore(storeName)
        await store.clear()
      }

      checkOfflineDataSize()
      return true
    } catch (error) {
      console.error('Failed to clear offline data:', error)
      return false
    }
  }, [checkOfflineDataSize])

  // Prefetch critical data
  const prefetchData = useCallback(async (urls: string[]) => {
    if (!('serviceWorker' in navigator)) {
      return false
    }

    try {
      const controller = navigator.serviceWorker.controller
      if (controller) {
        controller.postMessage({
          type: 'CACHE_URLS',
          payload: urls,
        })
        return true
      }
      return false
    } catch (error) {
      console.error('Failed to prefetch data:', error)
      return false
    }
  }, [])

  // Setup event listeners
  useEffect(() => {
    const handleOnline = () => {
      setState((prev) => ({ ...prev, isOnline: true }))
      onStatusChange?.(true)

      if (enableAutoSync) {
        triggerSync()
      }
    }

    const handleOffline = () => {
      setState((prev) => ({ ...prev, isOnline: false }))
      onStatusChange?.(false)
    }

    const handleMessage = (event: MessageEvent) => {
      if (event.data && event.data.type === 'SYNC_COMPLETE') {
        setState((prev) => ({
          ...prev,
          isSyncing: false,
          lastSyncTime: new Date(event.data.data.timestamp),
          syncQueue: 0,
        }))
        onSyncComplete?.()
        checkOfflineDataSize()
      }
    }

    window.addEventListener('online', handleOnline)
    window.addEventListener('offline', handleOffline)

    if ('serviceWorker' in navigator) {
      navigator.serviceWorker.addEventListener('message', handleMessage)
    }

    // Initialize
    initDatabase()
    registerServiceWorker()

    // Setup auto-sync
    if (enableAutoSync && navigator.onLine) {
      syncTimeoutRef.current = setInterval(() => {
        if (state.syncQueue > 0 && navigator.onLine) {
          triggerSync()
        }
      }, syncInterval)
    }

    return () => {
      window.removeEventListener('online', handleOnline)
      window.removeEventListener('offline', handleOffline)

      if ('serviceWorker' in navigator) {
        navigator.serviceWorker.removeEventListener('message', handleMessage)
      }

      if (syncTimeoutRef.current) {
        clearInterval(syncTimeoutRef.current)
      }

      if (dbRef.current) {
        dbRef.current.close()
      }
    }
  }, [
    enableAutoSync,
    syncInterval,
    onStatusChange,
    onSyncComplete,
    initDatabase,
    registerServiceWorker,
    triggerSync,
    checkOfflineDataSize,
    state.syncQueue,
  ])

  return {
    ...state,
    triggerSync,
    addToOfflineQueue,
    clearOfflineData,
    prefetchData,
    checkOfflineDataSize,
  }
}

// Export convenience hooks
export function useIsOnline() {
  const [isOnline, setIsOnline] = useState(navigator.onLine)

  useEffect(() => {
    const handleOnline = () => setIsOnline(true)
    const handleOffline = () => setIsOnline(false)

    window.addEventListener('online', handleOnline)
    window.addEventListener('offline', handleOffline)

    return () => {
      window.removeEventListener('online', handleOnline)
      window.removeEventListener('offline', handleOffline)
    }
  }, [])

  return isOnline
}

export function useNetworkStatus() {
  const [status, setStatus] = useState<{
    online: boolean
    effectiveType?: string
    downlink?: number
    rtt?: number
    saveData?: boolean
  }>({
    online: navigator.onLine,
  })

  useEffect(() => {
    const updateStatus = () => {
      // @ts-ignore - connection is not standard yet
      const connection =
        navigator.connection || navigator.mozConnection || navigator.webkitConnection

      setStatus({
        online: navigator.onLine,
        effectiveType: connection?.effectiveType,
        downlink: connection?.downlink,
        rtt: connection?.rtt,
        saveData: connection?.saveData,
      })
    }

    updateStatus()

    window.addEventListener('online', updateStatus)
    window.addEventListener('offline', updateStatus)

    // @ts-ignore
    if (navigator.connection) {
      // @ts-ignore
      navigator.connection.addEventListener('change', updateStatus)
    }

    return () => {
      window.removeEventListener('online', updateStatus)
      window.removeEventListener('offline', updateStatus)

      // @ts-ignore
      if (navigator.connection) {
        // @ts-ignore
        navigator.connection.removeEventListener('change', updateStatus)
      }
    }
  }, [])

  return status
}

/**
 * usePromptLog Hook
 * React hook for easy integration of prompt logging in components
 */

import { useCallback, useEffect, useRef } from 'react'
import promptLogService from '../services/promptLogService'
import { useAuth } from '../contexts/AuthContext'
import { useToast } from '../components/ui/use-toast'

export const usePromptLog = (options = {}) => {
  const { user } = useAuth()
  const { toast } = useToast()
  const promptIdRef = useRef(null)
  const responseIdRef = useRef(null)

  // Default options
  const config = {
    autoLog: true,
    includeContext: true,
    category: 'general',
    tags: [],
    ...options,
  }

  /**
   * Log a prompt
   */
  const logPrompt = useCallback(
    async (prompt, additionalData = {}) => {
      if (!config.autoLog) {
        return null
      }

      try {
        const promptId = await promptLogService.logPrompt({
          prompt,
          userId: user?.id || 'anonymous',
          source: additionalData.source || 'user-input',
          category: additionalData.category || config.category,
          tags: [...config.tags, ...(additionalData.tags || [])],
          context: config.includeContext
            ? {
                url: window.location.href,
                timestamp: Date.now(),
                ...additionalData.context,
              }
            : additionalData.context,
          ...additionalData,
        })

        promptIdRef.current = promptId
        return promptId
      } catch (error) {
        console.error('Failed to log prompt:', error)
        if (config.showErrors) {
          toast({
            title: 'Logging Error',
            description: 'Failed to log prompt',
            variant: 'destructive',
          })
        }
        return null
      }
    },
    [user, config, toast]
  )

  /**
   * Log a response
   */
  const logResponse = useCallback(
    async (response, additionalData = {}) => {
      if (!config.autoLog || !promptIdRef.current) {
        return null
      }

      try {
        const responseId = await promptLogService.logResponse(promptIdRef.current, {
          response,
          userId: user?.id || 'anonymous',
          model: additionalData.model || 'unknown',
          completionTime: additionalData.completionTime,
          totalTokens: additionalData.totalTokens,
          promptTokens: additionalData.promptTokens,
          completionTokens: additionalData.completionTokens,
          temperature: additionalData.temperature,
          maxTokens: additionalData.maxTokens,
          status: additionalData.status || 'completed',
          error: additionalData.error,
          latency: additionalData.latency,
          ...additionalData,
        })

        responseIdRef.current = responseId
        return responseId
      } catch (error) {
        console.error('Failed to log response:', error)
        if (config.showErrors) {
          toast({
            title: 'Logging Error',
            description: 'Failed to log response',
            variant: 'destructive',
          })
        }
        return null
      }
    },
    [user, config, toast]
  )

  /**
   * Log an interaction
   */
  const logInteraction = useCallback(
    async (action, data = {}) => {
      if (!config.autoLog) {
        return null
      }

      try {
        return await promptLogService.logInteraction({
          userId: user?.id || 'anonymous',
          promptId: promptIdRef.current,
          responseId: responseIdRef.current,
          action,
          ...data,
        })
      } catch (error) {
        console.error('Failed to log interaction:', error)
        return null
      }
    },
    [user, config]
  )

  /**
   * Log error
   */
  const logError = useCallback(
    async (error, context = {}) => {
      if (!config.autoLog) {
        return null
      }

      try {
        return await promptLogService.logResponse(promptIdRef.current, {
          response: '',
          userId: user?.id || 'anonymous',
          status: 'error',
          error: error.message || error.toString(),
          context,
        })
      } catch (err) {
        console.error('Failed to log error:', err)
        return null
      }
    },
    [user, config]
  )

  /**
   * Start a new conversation
   */
  const startConversation = useCallback(() => {
    promptIdRef.current = null
    responseIdRef.current = null
  }, [])

  /**
   * Get conversation history
   */
  const getHistory = useCallback(
    async (filters = {}) => {
      try {
        return await promptLogService.queryLogs({
          userId: user?.id || 'anonymous',
          ...filters,
        })
      } catch (error) {
        console.error('Failed to get history:', error)
        return []
      }
    },
    [user]
  )

  /**
   * Clear user logs
   */
  const clearUserLogs = useCallback(async () => {
    try {
// //       const userLogs = await promptLogService.queryLogs({ // TODO: Will be used in future // TODO: Will be used in future
        userId: user?.id || 'anonymous',
      })

      // Note: This would need to be implemented in the service
      // For now, we'll just clear all logs
      if (window.confirm('Clear all your logs? This cannot be undone.')) {
        await promptLogService.clearAllLogs()
        toast({
          title: 'Logs Cleared',
          description: 'Your logs have been cleared successfully',
        })
      }
    } catch (error) {
      console.error('Failed to clear logs:', error)
      toast({
        title: 'Error',
        description: 'Failed to clear logs',
        variant: 'destructive',
      })
    }
  }, [user, toast])

  /**
   * Export user logs
   */
  const exportLogs = useCallback(
    async (format = 'json') => {
      try {
        const exportData = await promptLogService.exportLogs(format, {
          userId: user?.id || 'anonymous',
        })

        const blob = new Blob([exportData], {
          type: format === 'json' ? 'application/json' : 'text/plain',
        })
        const url = URL.createObjectURL(blob)
        const a = document.createElement('a')
        a.href = url
        a.download = `prompt-logs-${Date.now()}.${format}`
        document.body.appendChild(a)
        a.click()
        document.body.removeChild(a)
        URL.revokeObjectURL(url)

        toast({
          title: 'Export Successful',
          description: `Logs exported as ${format.toUpperCase()}`,
        })
      } catch (error) {
        console.error('Failed to export logs:', error)
        toast({
          title: 'Export Failed',
          description: error.message,
          variant: 'destructive',
        })
      }
    },
    [user, toast]
  )

  /**
   * Get statistics
   */
  const getStatistics = useCallback(async (timeRange = null) => {
    try {
      return await promptLogService.getStatistics(timeRange)
    } catch (error) {
      console.error('Failed to get statistics:', error)
      return null
    }
  }, [])

  // Clean up on unmount
  useEffect(() => {
    return () => {
      // Flush any pending logs
      promptLogService.flush()
    }
  }, [])

  return {
    logPrompt,
    logResponse,
    logInteraction,
    logError,
    startConversation,
    getHistory,
    clearUserLogs,
    exportLogs,
    getStatistics,
    currentPromptId: promptIdRef.current,
    currentResponseId: responseIdRef.current,
  }
}

export default usePromptLog

/**
 * Core Web Vitals Optimization System
 * Automatically measures and optimizes LCP, FID, and CLS
 */

import { onCLS, onINP, onFCP, onLCP, onTTFB } from 'web-vitals'

class CoreWebVitalsOptimizer {
  constructor() {
    this.metrics = new Map()
    this.observers = []
    this.isOptimizationEnabled = true
    this.thresholds = {
      lcp: { good: 2500, needsImprovement: 4000 },
      inp: { good: 200, needsImprovement: 500 },
      cls: { good: 0.1, needsImprovement: 0.25 },
      fcp: { good: 1800, needsImprovement: 3000 },
      ttfb: { good: 800, needsImprovement: 1800 },
    }

    this.initializeTracking()
  }

  initializeTracking() {
    if (typeof window === 'undefined') {
      return
    }

    console.log('🚀 Core Web Vitals optimization system initialized')

    // Track all Core Web Vitals
    this.trackLCP()
    this.trackINP()
    this.trackCLS()
    this.trackFCP()
    this.trackTTFB()

    // Initialize optimization strategies
    this.optimizeLCP()
    this.optimizeINP()
    this.optimizeCLS()

    // Send metrics to analytics
    this.setupAnalyticsReporting()
  }

  trackLCP() {
    onLCP(
      (metric) => {
        this.metrics.set('lcp', metric)
        this.analyzeMetric('lcp', metric.value)
        this.sendToAnalytics('lcp', metric)
      },
      { reportAllChanges: true }
    )
  }

  trackINP() {
    onINP(
      (metric) => {
        this.metrics.set('inp', metric)
        this.analyzeMetric('inp', metric.value)
        this.sendToAnalytics('inp', metric)
      },
      { reportAllChanges: true }
    )
  }

  trackCLS() {
    onCLS(
      (metric) => {
        this.metrics.set('cls', metric)
        this.analyzeMetric('cls', metric.value)
        this.sendToAnalytics('cls', metric)
      },
      { reportAllChanges: true }
    )
  }

  trackFCP() {
    onFCP(
      (metric) => {
        this.metrics.set('fcp', metric)
        this.analyzeMetric('fcp', metric.value)
        this.sendToAnalytics('fcp', metric)
      },
      { reportAllChanges: true }
    )
  }

  trackTTFB() {
    onTTFB(
      (metric) => {
        this.metrics.set('ttfb', metric)
        this.analyzeMetric('ttfb', metric.value)
        this.sendToAnalytics('ttfb', metric)
      },
      { reportAllChanges: true }
    )
  }

  analyzeMetric(metricName, value) {
    const thresholds = this.thresholds[metricName]
    if (!thresholds) {
      return
    }

    let status = 'poor'
    if (value <= thresholds.good) {
      status = 'good'
    } else if (value <= thresholds.needsImprovement) {
      status = 'needs-improvement'
    }

    console.log(
      `📊 ${metricName.toUpperCase()}: ${value}${metricName === 'cls' ? '' : 'ms'} (${status})`
    )

    // Trigger optimization if needed
    if (status !== 'good' && this.isOptimizationEnabled) {
      this.triggerOptimization(metricName, value, status)
    }
  }

  triggerOptimization(metricName, _value, _status) {
    const optimizations = {
      lcp: () => this.optimizeLCPDynamic(),
      inp: () => this.optimizeINPDynamic(),
      cls: () => this.optimizeCLSDynamic(),
      fcp: () => this.optimizeFCPDynamic(),
      ttfb: () => this.optimizeTTFBDynamic(),
    }

    if (optimizations[metricName]) {
      console.log(`🔧 Triggering ${metricName.toUpperCase()} optimization...`)
      optimizations[metricName]()
    }
  }

  // LCP Optimization Strategies
  optimizeLCP() {
    // Preload critical resources
    this.preloadCriticalResources()

    // Optimize images
    this.optimizeImages()

    // Eliminate render-blocking resources
    this.eliminateRenderBlocking()
  }

  optimizeLCPDynamic() {
    // Dynamic LCP optimization based on current page
    const largestElements = this.findLargestContentfulElements()

    largestElements.forEach((element) => {
      if (element.tagName === 'IMG') {
        this.optimizeImageElement(element)
      } else if (element.tagName === 'VIDEO') {
        this.optimizeVideoElement(element)
      }
    })
  }

  findLargestContentfulElements() {
    const elements = []
    const observer = new PerformanceObserver((list) => {
      for (const entry of list.getEntries()) {
        if (entry.element) {
          elements.push(entry.element)
        }
      }
    })

    try {
      observer.observe({ entryTypes: ['largest-contentful-paint'] })
    } catch (e) {
      console.warn('LCP observer not supported')
    }

    return elements
  }

  preloadCriticalResources() {
    const criticalResources = [
      '/assets/css/critical.css',
      '/assets/fonts/inter-var.woff2',
      '/assets/js/critical.js',
    ]

    criticalResources.forEach((resource) => {
      if (!document.querySelector(`link[href="${resource}"]`)) {
        const link = document.createElement('link')
        link.rel = 'preload'
        link.href = resource

        if (resource.endsWith('.css')) {
          link.as = 'style'
        } else if (resource.endsWith('.woff2')) {
          link.as = 'font'
          link.type = 'font/woff2'
          link.crossOrigin = 'anonymous'
        } else if (resource.endsWith('.js')) {
          link.as = 'script'
        }

        document.head.appendChild(link)
      }
    })
  }

  optimizeImages() {
    const images = document.querySelectorAll('img[data-src], img[loading="lazy"]')

    // Implement intersection observer for lazy loading
    if ('IntersectionObserver' in window) {
      const imageObserver = new IntersectionObserver(
        (entries) => {
          entries.forEach((entry) => {
            if (entry.isIntersecting) {
              const img = entry.target
              if (img.dataset.src) {
                img.src = img.dataset.src
                img.removeAttribute('data-src')
              }
              imageObserver.unobserve(img)
            }
          })
        },
        {
          rootMargin: '50px',
        }
      )

      images.forEach((img) => imageObserver.observe(img))
    }
  }

  optimizeImageElement(img) {
    // Add responsive image attributes if not present
    if (!img.srcset && img.src) {
      const baseSrc = img.src.replace(/\.[^/.]+$/, '')
      const ext = img.src.split('.').pop()

      img.srcset = [
        `${baseSrc}_400w.${ext} 400w`,
        `${baseSrc}_800w.${ext} 800w`,
        `${baseSrc}_1200w.${ext} 1200w`,
      ].join(', ')

      img.sizes = '(max-width: 400px) 400px, (max-width: 800px) 800px, 1200px'
    }

    // Add loading attribute
    if (!img.loading) {
      img.loading = 'lazy'
    }

    // Add decode attribute
    if (!img.decode) {
      img.decode = 'async'
    }
  }

  eliminateRenderBlocking() {
    // Move non-critical CSS to load asynchronously
    const nonCriticalCSS = document.querySelectorAll('link[rel="stylesheet"]:not([data-critical])')

    nonCriticalCSS.forEach((link) => {
      const newLink = document.createElement('link')
      newLink.rel = 'preload'
      newLink.as = 'style'
      newLink.href = link.href
      newLink.onload = function () {
        this.onload = null
        this.rel = 'stylesheet'
      }

      document.head.appendChild(newLink)
      link.remove()
    })
  }

  // INP Optimization Strategies
  optimizeINP() {
    // Break up long tasks
    this.breakUpLongTasks()

    // Use web workers for heavy computations
    this.delegateToWebWorkers()

    // Optimize event handlers
    this.optimizeEventHandlers()
  }

  optimizeINPDynamic() {
    // Monitor long tasks and break them up
    if ('PerformanceLongTaskTiming' in window) {
      const observer = new PerformanceObserver((list) => {
        for (const entry of list.getEntries()) {
          if (entry.duration > 50) {
            console.warn(`Long task detected: ${entry.duration}ms`)
            // Could implement task scheduling here
          }
        }
      })

      try {
        observer.observe({ entryTypes: ['longtask'] })
      } catch (e) {
        console.warn('Long task observer not supported')
      }
    }
  }

  breakUpLongTasks() {
    // Implement task scheduler for breaking up long tasks
    window.yieldToMain = function () {
      return new Promise((resolve) => {
        setTimeout(resolve, 0)
      })
    }
  }

  delegateToWebWorkers() {
    // Create web worker for heavy computations
    if (typeof Worker !== 'undefined') {
      try {
        const workerBlob = new Blob(
          [
            `
          self.onmessage = function(e) {
            const { type, data } = e.data;

            switch(type) {
              case 'heavy-computation':
                // Perform heavy computation
                const result = performHeavyComputation(data);
                self.postMessage({ type: 'computation-result', result });
                break;
            }
          };

          function performHeavyComputation(data) {
            // Placeholder for heavy computation
            return data;
          }
        `,
          ],
          { type: 'application/javascript' }
        )

        this.worker = new Worker(URL.createObjectURL(workerBlob))
        this.worker.onmessage = (e) => {
          const { type } = e.data
          if (type === 'computation-result') {
            // Handle result
            console.log('Web worker computation completed')
          }
        }
      } catch (e) {
        console.warn('Web worker creation failed:', e)
      }
    }
  }

  optimizeEventHandlers() {
    // Add passive event listeners where appropriate
    const passiveEvents = ['touchstart', 'touchmove', 'wheel', 'scroll']

    passiveEvents.forEach((_eventType) => {
      // Override addEventListener to use passive listeners
      const originalAddEventListener = EventTarget.prototype.addEventListener
      EventTarget.prototype.addEventListener = function (type, listener, options) {
        if (passiveEvents.includes(type) && typeof options !== 'object') {
          options = { passive: true }
        }
        return originalAddEventListener.call(this, type, listener, options)
      }
    })
  }

  // CLS Optimization Strategies
  optimizeCLS() {
    // Set explicit dimensions for dynamic content
    this.setExplicitDimensions()

    // Preload fonts
    this.preloadFonts()

    // Reserve space for ads/embeds
    this.reserveSpaceForDynamicContent()
  }

  optimizeCLSDynamic() {
    // Monitor layout shifts and fix them
    if ('LayoutShift' in window) {
      const observer = new PerformanceObserver((list) => {
        for (const entry of list.getEntries()) {
          if (entry.hadRecentInput) {
            continue
          }

          console.warn(`Layout shift detected: ${entry.value}`)
          this.fixLayoutShift(entry)
        }
      })

      try {
        observer.observe({ entryTypes: ['layout-shift'] })
      } catch (e) {
        console.warn('Layout shift observer not supported')
      }
    }
  }

  setExplicitDimensions() {
    // Set dimensions for images without them
    const images = document.querySelectorAll('img:not([width]):not([height])')
    images.forEach((img) => {
      img.style.aspectRatio = '16 / 9' // Default aspect ratio
    })

    // Set min-height for dynamic content containers
    const dynamicContainers = document.querySelectorAll('[data-dynamic-content]')
    dynamicContainers.forEach((container) => {
      if (!container.style.minHeight) {
        container.style.minHeight = '200px' // Default minimum height
      }
    })
  }

  preloadFonts() {
    const criticalFonts = ['/assets/fonts/inter-var.woff2', '/assets/fonts/inter-bold.woff2']

    criticalFonts.forEach((fontUrl) => {
      if (!document.querySelector(`link[href="${fontUrl}"]`)) {
        const link = document.createElement('link')
        link.rel = 'preload'
        link.as = 'font'
        link.type = 'font/woff2'
        link.crossOrigin = 'anonymous'
        link.href = fontUrl
        document.head.appendChild(link)
      }
    })
  }

  reserveSpaceForDynamicContent() {
    // Reserve space for components that load asynchronously
    const asyncComponents = document.querySelectorAll('[data-async-component]')

    asyncComponents.forEach((component) => {
      const placeholder = document.createElement('div')
      placeholder.style.height = component.dataset.expectedHeight || '300px'
      placeholder.style.backgroundColor = '#f0f0f0'
      placeholder.style.borderRadius = '4px'
      placeholder.className = 'async-placeholder'

      component.parentNode.insertBefore(placeholder, component)

      // Remove placeholder when component loads
      const observer = new MutationObserver(() => {
        if (component.children.length > 0) {
          placeholder.remove()
          observer.disconnect()
        }
      })

      observer.observe(component, { childList: true })
    })
  }

  fixLayoutShift(entry) {
    // Attempt to fix layout shifts automatically
    entry.sources.forEach((source) => {
      if (source.node) {
        const element = source.node

        // Add transition to smooth layout changes
        if (!element.style.transition) {
          element.style.transition = 'all 0.2s ease-out'
        }
      }
    })
  }

  // Analytics and Reporting
  setupAnalyticsReporting() {
    // Send metrics to Google Analytics or custom analytics
    this.sendToGoogleAnalytics()

    // Send to custom dashboard
    this.sendToCustomDashboard()
  }

  sendToAnalytics(metricName, metric) {
    // Google Analytics 4
    if (typeof gtag !== 'undefined') {
      gtag('event', metricName, {
        event_category: 'Core Web Vitals',
        event_label: metricName.toUpperCase(),
        value: Math.round(metric.value),
        custom_map: { metric_id: metric.id },
      })
    }

    // Custom analytics
    this.sendToCustomAnalytics(metricName, metric)
  }

  sendToGoogleAnalytics() {
    // Enhanced ecommerce tracking for performance
    if (typeof gtag !== 'undefined') {
      gtag('config', 'GA_MEASUREMENT_ID', {
        custom_map: {
          lcp: 'largest_contentful_paint',
          inp: 'interaction_to_next_paint',
          cls: 'cumulative_layout_shift',
        },
      })
    }
  }

  sendToCustomAnalytics(metricName, metric) {
    // Send to custom performance monitoring service
    const payload = {
      metric: metricName,
      value: metric.value,
      id: metric.id,
      timestamp: Date.now(),
      url: window.location.href,
      userAgent: navigator.userAgent,
      connectionType: navigator.connection?.effectiveType || 'unknown',
    }

    // Use sendBeacon for reliable delivery
    if (navigator.sendBeacon) {
      navigator.sendBeacon('/api/analytics/core-web-vitals', JSON.stringify(payload))
    } else {
      // Fallback to fetch
      fetch('/api/analytics/core-web-vitals', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload),
      }).catch(console.error)
    }
  }

  sendToCustomDashboard() {
    // Aggregate metrics and send to dashboard
    setTimeout(() => {
      const allMetrics = {}
      this.metrics.forEach((metric, name) => {
        allMetrics[name] = {
          value: metric.value,
          rating: this.getMetricRating(name, metric.value),
          timestamp: metric.entries?.[0]?.startTime || Date.now(),
        }
      })

      this.sendToDashboard(allMetrics)
    }, 5000) // Wait 5 seconds to collect all metrics
  }

  getMetricRating(metricName, value) {
    const thresholds = this.thresholds[metricName]
    if (!thresholds) {
      return 'unknown'
    }

    if (value <= thresholds.good) {
      return 'good'
    }
    if (value <= thresholds.needsImprovement) {
      return 'needs-improvement'
    }
    return 'poor'
  }

  sendToDashboard(metrics) {
    const payload = {
      url: window.location.href,
      timestamp: Date.now(),
      metrics,
      userAgent: navigator.userAgent,
      viewport: {
        width: window.innerWidth,
        height: window.innerHeight,
      },
      connection: navigator.connection
        ? {
            effectiveType: navigator.connection.effectiveType,
            downlink: navigator.connection.downlink,
            rtt: navigator.connection.rtt,
          }
        : null,
    }

    fetch('/api/dashboard/core-web-vitals', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload),
    }).catch(console.error)
  }

  // Optimization Features
  optimizeFCPDynamic() {
    // Remove unused CSS
    this.removeUnusedCSS()

    // Optimize critical rendering path
    this.optimizeCriticalRenderingPath()
  }

  optimizeTTFBDynamic() {
    // Implement service worker caching
    this.optimizeServerResponse()

    // Use CDN for static assets
    this.optimizeCDN()
  }

  removeUnusedCSS() {
    // This would require a more sophisticated implementation
    // For now, we'll add a performance hint
    console.info('💡 Consider using PurgeCSS to remove unused CSS')
  }

  optimizeCriticalRenderingPath() {
    // Inline critical CSS
    const criticalCSS = this.extractCriticalCSS()
    if (criticalCSS) {
      const style = document.createElement('style')
      style.textContent = criticalCSS
      document.head.insertBefore(style, document.head.firstChild)
    }
  }

  extractCriticalCSS() {
    // This is a simplified version - real implementation would be more complex
    return `
      body { font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif; }
      .critical { display: block; }
      .loader { animation: spin 1s linear infinite; }
      @keyframes spin { 0% { transform: rotate(0deg); } 100% { transform: rotate(360deg); } }
    `
  }

  optimizeServerResponse() {
    console.info('💡 Consider implementing server-side caching and CDN')
  }

  optimizeCDN() {
    console.info('💡 Consider using a CDN for static assets')
  }

  // Cleanup
  cleanup() {
    this.observers.forEach((observer) => observer.disconnect())
