// メールサービスクラス
export class EmailService {
  private static transporter = createTransporter()

  // メイン送信機能
  static async sendEmail(emailData: EmailData): Promise<{
    success: boolean
    messageId?: string
    error?: string
  }> {
    try {
      // 入力検証
      const validatedData = emailDataSchema.parse(emailData)

      let htmlContent = validatedData.html
      let textContent = validatedData.text
      let subject = validatedData.subject

      // テンプレートを使用する場合
      if (validatedData.template) {
        const template = await this.renderTemplate(validatedData.template, validatedData.data)

        htmlContent = template.html
        textContent = template.text
        subject = template.subject || validatedData.subject
      }

      // メール送信
      const result = await this.transporter.sendMail({
        from: `${EMAIL_CONFIG.from.name} <${EMAIL_CONFIG.from.address}>`,
        to: validatedData.to,
        cc: validatedData.cc,
        bcc: validatedData.bcc,
        subject,
        html: htmlContent,
        text: textContent,
        attachments: validatedData.attachments,
        priority: validatedData.priority,
        headers: {
          'X-PM-LM-Tracking': validatedData.trackingEnabled ? '1' : '0',
        },
      })

      if (process.env.NODE_ENV === 'development') {
        logger.debug(`メール送信成功: ${result.messageId}`)
      }

      return {
        success: true,
        messageId: result.messageId,
      }
    } catch (error) {
      if (process.env.NODE_ENV === 'development') {
        logger.error('メール送信エラー:', error)
      }

      return {
        success: false,
        error: error instanceof Error ? error.message : 'Unknown error',
      }
    }
  }

  // テンプレートレンダリング
  private static async renderTemplate(
    templateName: string,
    data: Record<string, unknown>
  ): Promise<EmailTemplate> {
    try {
      let template: EmailTemplate

      // 特定のテンプレートを読み込み
      try {
        template = await EmailTemplateLoader.loadTemplate(templateName)
      } catch {
        // テンプレートが見つからない場合はデフォルトを使用
        if (process.env.NODE_ENV === 'development') {
          logger.warn(
            `テンプレート ${templateName} が見つかりません。デフォルトテンプレートを使用します。`
          )
        }
        template = EmailTemplateLoader.getDefaultTemplate()
      }

      // Handlebarsでレンダリング
      const subjectTemplate = Handlebars.compile(template.subject)
      const htmlTemplate = Handlebars.compile(template.html)
      const textTemplate = template.text ? Handlebars.compile(template.text) : null

      return {
        subject: subjectTemplate(data),
        html: htmlTemplate(data),
        text: textTemplate ? textTemplate(data) : undefined,
      }
    } catch (error) {
      if (process.env.NODE_ENV === 'development') {
        logger.error('テンプレートレンダリングエラー:', error)
      }
      throw new TRPCError({
        code: 'INTERNAL_SERVER_ERROR',
        message: 'メールテンプレートの処理中にエラーが発生しました',
      })
    }
  }

  // バルクメール送信
  static async sendBulkEmail(
    recipients: string[],
    emailData: Omit<EmailData, 'to'>
  ): Promise<{
    totalRecipients: number
    successCount: number
    failureCount: number
    errors: Array<{ email: string; error: string }>
  }> {
    const totalRecipients = recipients.length
    let successCount = 0
    let failureCount = 0
    const errors: Array<{ email: string; error: string }> = []

    // バッチサイズを制限（SMTP制限を考慮）
    const batchSize = 10
    const batches = []

    for (let i = 0; i < recipients.length; i += batchSize) {
      batches.push(recipients.slice(i, i + batchSize))
    }

    for (const batch of batches) {
      const promises = batch.map(async (email) => {
        try {
          const result = await this.sendEmail({
            ...emailData,
            to: email,
          })

          if (result.success) {
            successCount++
          } else {
            failureCount++
            errors.push({ email, error: result.error || 'Unknown error' })
          }
        } catch (error) {
          failureCount++
          errors.push({
            email,
            error: error instanceof Error ? error.message : 'Unknown error',
          })
        }
      })

      // バッチ内並行処理
      await Promise.allSettled(promises)

      // レート制限を考慮した間隔
      if (batches.indexOf(batch) < batches.length - 1) {
        await new Promise((resolve) => setTimeout(resolve, 1000))
      }
    }

    return {
      totalRecipients,
      successCount,
      failureCount,
      errors,
    }
  }

  // メール配信可能性チェック
  static async verifyConnection(): Promise<{
    success: boolean
    error?: string
  }> {
    try {
      await this.transporter.verify()
      return { success: true }
    } catch (error) {
      if (process.env.NODE_ENV === 'development') {
        logger.error('SMTP接続確認エラー:', error)
      }
      return {
        success: false,
        error: error instanceof Error ? error.message : 'Connection failed',
      }
    }
  }

  // メールアドレス検証
  static validateEmail(email: string): boolean {
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/
    return emailRegex.test(email)
  }

  // 配信停止処理
  static async unsubscribe(email: string, type: string): Promise<void> {
    // 実装に応じて配信停止リストに追加
    // 例: データベースに記録、外部サービスAPI呼び出しなど
    if (process.env.NODE_ENV === 'development') {
      logger.debug(`配信停止登録: ${email} (type: ${type})`)
    }
  }

  // メール送信統計取得
  static async getEmailStats(
    _startDate: Date,
    _endDate: Date
  ): Promise<{
    totalSent: number
    successRate: number
    bounceRate: number
    unsubscribeRate: number
  }> {
    // 実装に応じてメール送信履歴から統計を計算
    // 現在はモック実装
    return {
      totalSent: 0,
      successRate: 0,
      bounceRate: 0,
      unsubscribeRate: 0,
    }
  }
}

